function checkSettingsNormalization() {
  const sandbox = loadSettingsSandbox();
  const normalize = sandbox.ATPNormalizeSettings;
  assert(typeof normalize === 'function', 'defaults must expose ATPNormalizeSettings');
  const settings = normalize({
    enabled: 'false',
    siteConfigs: null,
    unknownTopLevel: 'drop',
    gridCols: '999',
    visibleRows: 'bad',
    backgroundSpeed: 'invalid',
    pauseWhenHidden: 'false'
  });
  assert(settings.enabled === false, 'settings normalization must preserve disabled string values');
  assert(settings.siteConfigs && typeof settings.siteConfigs === 'object' && !Array.isArray(settings.siteConfigs), 'settings normalization must repair invalid siteConfigs');
  assert(settings.gridCols === 32, 'settings normalization must clamp numeric settings to the public schema max');
  assert(settings.debugLogging === false, 'legacy settings must normalize to DEBUG logging disabled without changing existing fields');
  assert(sandbox.ATPGetSettingApplyMode('gridCols') === 'hotReload', 'schema non-immediate settings must map to hot reload');
  assert(sandbox.ATPGetSettingApplyMode('firstScreenConcurrency') === 'live', 'image concurrency settings must support live scheduler reconfiguration');
  assert(sandbox.ATPGetSettingApplyMode('imageTimeout') === 'live', 'image timeout must apply live to new attempts');
  assert(sandbox.ATPGetSettingApplyMode('heavyPreviewStarvationWait') === 'live', 'schema immediate settings must map to live apply');
  assert(sandbox.ATPGetSettingsApplyMode(['heavyPreviewStarvationWait', 'gridCols']) === 'hotReload', 'settings apply mode aggregation must prefer hot reload over live');
  assert(sandbox.ATPGetSettingsApplyMode(['gridCols', 'enabled']) === 'pageReload', 'settings apply mode aggregation must prefer page reload for extension state changes');
  assert(settings.visibleRows === 2, 'settings normalization must fall back invalid numeric settings to defaults');
  assert(settings.backgroundSpeed === 'normal', 'settings normalization must fall back invalid select values to defaults');
  assert(settings.pauseWhenHidden === false, 'settings normalization must preserve false boolean string values');
  assert(!Object.prototype.hasOwnProperty.call(settings, 'unknownTopLevel'), 'settings normalization must drop unknown top-level fields');

  const siteSettings = normalize({
    siteConfigs: {
      'valid.example': { disabled: 'true', note: 'drop' },
      'bad/example': { disabled: true },
      '..bad.example': { disabled: true },
      'empty.example': { note: 'drop' }
    }
  });
  assert(siteSettings.siteConfigs['valid.example'].disabled === true, 'settings normalization must keep valid site disabled flags');
  assert(!Object.prototype.hasOwnProperty.call(siteSettings.siteConfigs['valid.example'], 'note'), 'settings normalization must drop unknown site config fields');
  assert(!siteSettings.siteConfigs['bad/example'], 'settings normalization must drop invalid site config hosts');
  assert(!siteSettings.siteConfigs['..bad.example'], 'settings normalization must drop malformed site config hosts');
  assert(!siteSettings.siteConfigs['empty.example'], 'settings normalization must drop site configs without a disabled flag');

  const tuned = normalize({
    firstScreenConcurrency: '999',
    backgroundConcurrency: '999',
    heavyImageConcurrency: '999',
    heavyThumbnailClarity: 'lightweight',
    heavyPreviewStarvationWait: '999',
    heavyPreviewStarvationMP: '99999',
    heavyRestoreFastBatchSize: '999',
    heavyRestorePressureBatchSize: '999',
    backgroundSpeed: 'extreme'
  });
  assert(tuned.firstScreenConcurrency === 128, 'first-screen concurrency must use the expanded public schema range');
  assert(tuned.backgroundConcurrency === 128, 'ordinary background concurrency must use the expanded public schema range');
  assert(tuned.heavyImageConcurrency === 128, 'heavy image concurrency must use the expanded public schema range');
  assert(tuned.heavyThumbnailClarity === 'lightweight', 'heavy thumbnail clarity must accept lightweight mode');
  assert(tuned.heavyPreviewStarvationWait === 120, 'heavy preview starvation wait must use the expanded public schema range');
  assert(tuned.heavyPreviewStarvationMP === 10000, 'heavy preview starvation MP must use the expanded public schema range');
  assert(tuned.heavyRestoreFastBatchSize === 128, 'low-pressure heavy restore batch size must use the expanded public schema range');
  assert(tuned.heavyRestorePressureBatchSize === 128, 'pressure heavy restore batch size must use the expanded public schema range');
  assert(tuned.backgroundSpeed === 'extreme', 'settings normalization must accept the 20ms background speed option');

  const low = normalize({
    heavyThumbnailClarity: 'invalid',
    heavyPreviewStarvationWait: '0',
    heavyPreviewStarvationMP: '1',
    heavyRestoreFastBatchSize: '0',
    heavyRestorePressureBatchSize: '0'
  });
  assert(low.heavyThumbnailClarity === 'balanced', 'invalid heavy thumbnail clarity must fall back to balanced mode');
  assert(low.heavyPreviewStarvationWait === 0, 'heavy preview starvation wait must support an immediate zero value');
  assert(low.heavyPreviewStarvationMP === 1, 'heavy preview starvation MP must preserve a valid low user value');
  assert(low.heavyRestoreFastBatchSize === 1, 'low-pressure heavy restore batch size must clamp to 1');
  assert(low.heavyRestorePressureBatchSize === 1, 'pressure heavy restore batch size must clamp to 1');

  const legacy = normalize({ heavyThumbnailClarity: 'blurred' });
  assert(legacy.heavyThumbnailClarity === 'lightweight', 'legacy blurred thumbnail clarity must migrate to lightweight mode');

  sandbox.SETTINGS_SCHEMA.forEach(function(item) {
    if (!item || item.type !== 'number' || item.step === undefined || item.min === undefined || item.default === undefined) return;
    assert(
      (Number(item.default) - Number(item.min)) % Number(item.step) === 0,
      'numeric setting defaults must align with their input step: ' + item.key
    );
  });
}

function createScannerSandbox(rowCount, options) {
  options = options || {};
  const queryCounts = {};
  const rows = [];
  for (let i = 0; i < rowCount; i++) {
    const invalidIconLink = {
      href: 'javascript:',
      closest: function() { return null; },
      textContent: 'invalid icon'
    };
    const link = {
      href: 'https://www.sehuatang.org/thread-' + i + '-1-1.html',
      closest: function() { return null; },
      textContent: 'thread ' + i
    };
    rows.push({
      id: 'normalthread_' + i,
      tagName: 'TBODY',
      classList: { contains: function() { return false; } },
      querySelector: function(selector) {
        if (selector.indexOf('atp-thumbnail-container') !== -1 || selector.indexOf('atp-thumb-row') !== -1) return null;
        if (options.invalidIconLink && selector === '.icn a[href]') return invalidIconLink;
        if (options.invalidIconLink && selector === 'a.xst[href]') return link;
        return selector.indexOf('a[href') !== -1 ? link : null;
      },
      closest: function() { return null; },
      textContent: 'thread ' + i,
      getBoundingClientRect: function() {
        return typeof options.rowRect === 'function' ? options.rowRect(i) : { top: 10, bottom: 80 };
      }
    });
  }
  const root = {
    matches: function() { return false; },
    querySelectorAll: function(selector) {
      queryCounts[selector] = (queryCounts[selector] || 0) + 1;
      return selector === 'tbody[id^="normalthread"]' ? rows : [];
    }
  };
  const sandbox = {
    console: console,
    window: {},
    document: {
      querySelector: function() { return rows[0] || null; },
      querySelectorAll: function(selector) {
        queryCounts.threadRoot = (queryCounts.threadRoot || 0) + 1;
        if (
          selector === '#threadlist' ||
          selector === '.threadlist' ||
          selector === 'table[id*="threadlist"]' ||
          selector === 'form[id*="moderate"]'
        ) {
          return [root];
        }
        return [];
      },
      contains: function(node) {
        return node === root || rows.indexOf(node) !== -1;
      }
    }
  };
  vm.createContext(sandbox);
  vm.runInContext(read('scanner.js') + '\nthis.ATPScanner = window.ATPScanner;', sandbox, {
    filename: 'scanner.js'
  });
  return { scanner: sandbox.ATPScanner, queryCounts: queryCounts };
}

function createScannerRootSelectionSandbox(options) {
  options = options || {};
  const link = {
    href: 'https://www.sehuatang.org/thread-' + (options.threadId || 99) + '-1-1.html',
    closest: function() { return null; },
    textContent: 'thread ' + (options.threadId || 99)
  };
  const row = {
    id: 'normalthread_' + (options.threadId || 99),
    tagName: 'TBODY',
    classList: { contains: function() { return false; } },
    querySelector: function(selector) {
      if (selector.indexOf('atp-thumbnail-container') !== -1 || selector.indexOf('atp-thumb-row') !== -1) return null;
      return selector.indexOf('a[href') !== -1 ? link : null;
    },
    closest: function() { return null; },
    textContent: 'thread 99'
  };
  const decoy = {
    matches: function() { return false; },
    querySelector: function(selector) {
      if (!options.decoyHasInvalidRow) return null;
      if (selector === 'tbody[id^="thread"]') {
        return {
          id: 'thread_ad',
          tagName: 'TBODY',
          classList: { contains: function() { return false; } },
          querySelector: function(q) {
            if (q.indexOf('atp-thumbnail-container') !== -1 || q.indexOf('atp-thumb-row') !== -1) return null;
            return q.indexOf('a[href') !== -1 ? { href: '#', closest: function() { return null; }, textContent: 'not a thread' } : null;
          }
        };
      }
      return null;
    },
    querySelectorAll: function(selector) {
      var row = this.querySelector(selector);
      return row ? [row] : [];
    }
  };
  const real = {
    matches: function() { return false; },
    querySelector: function(selector) {
      return selector === 'tbody[id^="normalthread"]' ? row : null;
    },
    querySelectorAll: function(selector) {
      return selector === 'tbody[id^="normalthread"]' ? [row] : [];
    }
  };
  const sandbox = {
    console: console,
    window: {},
    document: {
      querySelectorAll: function(selector) {
        if (selector === '#threadlist' && options.emptyPrimary) return [decoy];
        if (selector === '#threadlist') return [];
        if (selector === '.threadlist' || selector === 'table[id*="threadlist"]' || selector === 'form[id*="moderate"]') return [];
        if (selector === '.bm_c') return [decoy, real];
        return [];
      },
      querySelector: function(selector) { return real.querySelector(selector); }
    }
  };
  vm.createContext(sandbox);
  vm.runInContext(read('scanner.js') + '\nthis.ATPScanner = window.ATPScanner;', sandbox, {
    filename: 'scanner.js'
  });
  return sandbox.ATPScanner;
}

function createScannerDecoratedTbodySandbox(options) {
  options = options || {};
  const link = {
    href: 'https://www.sehuatang.org/thread-313-1-1.html',
    closest: function() { return null; },
    textContent: 'thread 313'
  };
  const thumbMarker = { className: 'atp-thumb-row' };
  const parentTbody = {
    id: 'normalthread_313',
    tagName: 'TBODY',
    classList: { contains: function(cls) { return !!options.parentProcessed && cls === 'atp-processed'; } },
    querySelector: function(selector) {
      if (selector.indexOf('atp-thumbnail-container') !== -1 || selector.indexOf('atp-thumb-row') !== -1) {
        return options.parentHasThumbnail ? thumbMarker : null;
      }
      return selector.indexOf('a[href') !== -1 ? link : null;
    },
    closest: function() { return null; },
    textContent: 'thread 313'
  };
  const childTr = {
    id: 'thread_313_child',
    tagName: 'TR',
    parentElement: parentTbody,
    classList: { contains: function() { return false; } },
    querySelector: function(selector) {
      if (selector.indexOf('atp-thumbnail-container') !== -1 || selector.indexOf('atp-thumb-row') !== -1) return null;
      return selector.indexOf('a[href') !== -1 ? link : null;
    },
    nextElementSibling: null,
    closest: function() { return null; },
    textContent: 'thread 313 child'
  };
  const root = {
    matches: function() { return false; },
    querySelector: function(selector) {
      if (selector === 'tbody[id^="normalthread"]') return parentTbody;
      if (selector === 'tr[id^="thread"]') return childTr;
      return null;
    },
    querySelectorAll: function(selector) {
      if (selector === 'tbody[id^="normalthread"]') return [parentTbody];
      if (selector === 'tr[id^="thread"]') return [childTr];
      return [];
    }
  };
  const sandbox = {
    console: console,
    Node: { DOCUMENT_POSITION_FOLLOWING: 4 },
    window: {},
    document: {
      querySelectorAll: function(selector) {
        return selector === '#threadlist' ? [root] : [];
      },
      querySelector: function(selector) { return root.querySelector(selector); }
    }
  };
  vm.createContext(sandbox);
  vm.runInContext(read('scanner.js') + '\nthis.ATPScanner = window.ATPScanner;', sandbox, {
    filename: 'scanner.js'
  });
  return { scanner: sandbox.ATPScanner, parentTbody: parentTbody, childTr: childTr };
}

function checkScannerDecoratedTbodyGuard() {
  let sandbox = createScannerDecoratedTbodySandbox({ parentHasThumbnail: true });
  assert(sandbox.scanner.isDecoratedArticleContainer(sandbox.childTr) === true, 'scanner decorated-container helper must detect child TRs under decorated TBODYs');
  let results = sandbox.scanner.detectArticleContainers({
    limit: 5,
    skipServiceThreads: false
  });
  assert(results.length === 0, 'scanner must not return child TR candidates after parent TBODY thumbnail injection');

  sandbox = createScannerDecoratedTbodySandbox({ parentProcessed: true });
  assert(sandbox.scanner.isDecoratedArticleContainer(sandbox.childTr) === true, 'scanner decorated-container helper must detect child TRs under processed resource-only TBODYs');
  results = sandbox.scanner.detectArticleContainers({
    limit: 5,
    skipServiceThreads: false
  });
  assert(results.length === 0, 'scanner must not return child TR candidates after parent TBODY is marked processed');
}

function checkScannerCursorState() {
  let state = {};
  let sandbox = createScannerSandbox(120);
  const first = sandbox.scanner.detectArticleContainers({
    limit: 50,
    scanState: state,
    skipServiceThreads: false
  });
  const rootQueriesAfterFirst = sandbox.queryCounts.threadRoot;
  const second = sandbox.scanner.detectArticleContainers({
    limit: 50,
    scanState: state,
    skipServiceThreads: false
  });
  assert(first.length === 50, 'scanner cursor test must read the first 50 rows');
  assert(second.length === 50, 'scanner cursor test must read the second 50 rows');
  assert(second[0].link.href.indexOf('thread-50-') !== -1, 'scanner cursor must resume from the next unscanned row');
  assert(rootQueriesAfterFirst > 0, 'scanner cursor test must exercise thread root selection');
  assert(sandbox.queryCounts.threadRoot === rootQueriesAfterFirst, 'scanner cursor must reuse the validated thread root for the second batch');
  assert(sandbox.queryCounts['tbody[id^="normalthread"]'] === 1, 'scanner cursor must not rerun the first selector for the second batch');

  state = {};
  sandbox = createScannerSandbox(50);
  const exact = sandbox.scanner.detectArticleContainers({
    limit: 51,
    scanState: state,
    skipServiceThreads: false
  });
  assert(exact.length === 50, 'scanner sentinel scan must return exact-limit candidate sets');
  assert(state.exhausted === true, 'scanner sentinel scan must mark exact-limit candidate sets as exhausted');

  sandbox = createScannerSandbox(20);
  let serviceChecks = 0;
  sandbox.scanner.isForumServiceThread = function() {
    serviceChecks++;
    return false;
  };
  const rejected = sandbox.scanner.detectArticleContainers({
    limit: 20,
    skipServiceThreads: true,
    accept: function() { return false; }
  });
  assert(rejected.length === 0, 'scanner accept-order test must reject all candidates');
  assert(serviceChecks === 0, 'scanner must run cheap accept checks before reading service-thread text');

  state = {};
  sandbox = createScannerSandbox(60);
  let acceptCalls = 0;
  const offscreenFirst = sandbox.scanner.detectArticleContainers({
    limit: 5,
    nodeBudget: 12,
    scanState: state,
    skipServiceThreads: false,
    accept: function() {
      acceptCalls++;
      return false;
    }
  });
  const rootQueriesAfterOffscreenFirst = sandbox.queryCounts.threadRoot;
  assert(offscreenFirst.length === 0, 'scanner node budget test must reject all offscreen candidates');
  assert(acceptCalls === 12, 'scanner must bound per-pass candidate checks when accept rejects long offscreen lists');
  assert(state.exhausted === false, 'scanner node budget pause must leave the cursor resumable');
  const offscreenSecond = sandbox.scanner.detectArticleContainers({
    limit: 5,
    nodeBudget: 12,
    scanState: state,
    skipServiceThreads: false,
    accept: function() {
      acceptCalls++;
      return false;
    }
  });
  assert(offscreenSecond.length === 0 && acceptCalls === 24, 'scanner node budget test must resume from the next unscanned row');
  assert(sandbox.queryCounts.threadRoot === rootQueriesAfterOffscreenFirst, 'scanner node budget cursor must reuse the existing thread root across passes');
  assert(sandbox.queryCounts['tbody[id^="normalthread"]'] === 1, 'scanner node budget cursor must reuse the existing selector node list across passes');

  state = {};
  sandbox = createScannerSandbox(850, {
    rowRect: function(index) {
      const top = -10000 + index * 16;
      return { top: top, bottom: top + 12 };
    }
  });
  const seekFirst = sandbox.scanner.detectArticleContainers({
    limit: 5,
    nodeBudget: 12,
    scanState: state,
    seekViewportStart: true,
    viewportTop: -2000,
    skipServiceThreads: false
  });
  const seekFirstIndex = Number((seekFirst[0].link.href.match(/thread-(\d+)-/) || [])[1]);
  const selectorQueriesAfterSeekFirst = sandbox.queryCounts['tbody[id^="normalthread"]'];
  const seekSecond = sandbox.scanner.detectArticleContainers({
    limit: 5,
    nodeBudget: 12,
    scanState: state,
    seekViewportStart: true,
    viewportTop: -2000,
    skipServiceThreads: false
  });
  const seekSecondIndex = Number((seekSecond[0].link.href.match(/thread-(\d+)-/) || [])[1]);
  assert(seekFirst.length === 5, 'scanner viewport seek test must return a first near-viewport batch');
  assert(seekFirstIndex > 450 && seekFirstIndex < 520, 'scanner viewport seek must skip long above-viewport prefixes after cursor reset');
  assert(seekSecond.length === 5 && seekSecondIndex === seekFirstIndex + 5, 'scanner viewport seek must not restart from the viewport on cursor continuation');
  assert(sandbox.queryCounts['tbody[id^="normalthread"]'] === selectorQueriesAfterSeekFirst, 'scanner viewport seek continuation must reuse the active selector node list');

  sandbox = createScannerSandbox(1, { invalidIconLink: true });
  const fallbackLink = sandbox.scanner.detectArticleContainers({
    limit: 1,
    skipServiceThreads: false
  });
  assert(fallbackLink.length === 1, 'scanner article-link fallback test must still return rows when the icon link is unusable');
  assert(fallbackLink[0].link.href.indexOf('thread-0-') !== -1, 'scanner article-link fallback must skip unusable icon links and keep the real thread title link');

  let scanner = createScannerRootSelectionSandbox();
  const selected = scanner.detectArticleContainers({
    limit: 1,
    skipServiceThreads: false
  });
  assert(selected.length === 1, 'scanner root selection must skip broad containers without thread candidates');
  assert(selected[0].link.href.indexOf('thread-99-') !== -1, 'scanner root selection must use the broad container that actually contains thread rows');

  scanner = createScannerRootSelectionSandbox({ decoyHasInvalidRow: true, threadId: 100 });
  const invalidDecoy = scanner.detectArticleContainers({
    limit: 1,
    skipServiceThreads: false
  });
  assert(invalidDecoy.length === 1, 'scanner root selection must skip broad containers with candidate-looking rows but no usable thread link');
  assert(invalidDecoy[0].link.href.indexOf('thread-100-') !== -1, 'scanner root selection must continue to the real root after an invalid broad decoy');

  scanner = createScannerRootSelectionSandbox({ emptyPrimary: true, threadId: 101 });
  const emptyPrimary = scanner.detectArticleContainers({
    limit: 1,
    skipServiceThreads: false
  });
  assert(emptyPrimary.length === 1, 'scanner root selection must prefer populated broad roots over empty primary shells');
  assert(emptyPrimary[0].link.href.indexOf('thread-101-') !== -1, 'scanner root selection must not let an empty primary shell hide real thread rows');
}

async function checkFloatingPanelPartialSettingsSave() {
  const storage = {
    settings: {
      enabled: false,
      siteConfigs: {
        'example.com': { disabled: true }
      },
      gridCols: 5
    }
  };
  const sandbox = {
    console: console,
    document: {
      activeElement: null
    },
    SharedUtils: {
      isHeavyImageHost: loadSharedUtils().isHeavyImageHost,
      prepareArticleExtractionContext: loadSharedUtils().prepareArticleExtractionContext.bind(loadSharedUtils()),
      MESSAGE_TYPES: {
        SAVE_SETTINGS_PATCH: 'SAVE_SETTINGS_PATCH'
      }
    },
    chrome: {
      runtime: {
        lastError: null,
        sendMessage: function(message, callback) {
          if (!message || message.type !== 'SAVE_SETTINGS_PATCH') {
            callback({});
            return;
          }
          const patch = message.settingsPatch || {};
          const merged = Object.assign({}, storage.settings, patch);
          if (Object.prototype.hasOwnProperty.call(patch, 'siteConfigs')) {
            merged.siteConfigs = Object.assign({}, storage.settings.siteConfigs || {}, patch.siteConfigs || {});
          }
          storage.settings = merged;
          callback({ ok: true, settings: storage.settings });
        }
      },
      storage: {
        local: {
          get: async function(keys) {
            if (keys === 'settings') return { settings: storage.settings };
            return {};
          },
          set: async function(items) {
            Object.assign(storage, items || {});
          }
        }
      }
    }
  };
  vm.createContext(sandbox);
  vm.runInContext(read('settings-schema.js') + '\nthis.SETTINGS_SCHEMA = SETTINGS_SCHEMA;', sandbox, { filename: 'settings-schema.js' });
  vm.runInContext(read('defaults.js'), sandbox, { filename: 'defaults.js' });
  vm.runInContext(read('floating-panel.js') + '\nthis.FloatingPanel = FloatingPanel;', sandbox, {
    filename: 'floating-panel.js'
  });
  function createField(type, value) {
    return {
      type: type || 'number',
      value: value,
      checked: !!value,
      disabled: false,
      attrs: {
        'aria-invalid': 'true',
        'aria-describedby': 'bfp-msg'
      },
      setAttribute: function(name, val) {
        this.attrs[name] = String(val);
      },
      removeAttribute: function(name) {
        delete this.attrs[name];
      },
      getAttribute: function(name) {
        return this.attrs[name];
      }
    };
  }
  function createSettingsView(fields) {
    return {
      querySelector: function(selector) {
        if (/\.bfp-reset|\.bfp-heavy-preset/.test(selector)) return null;
        const match = /\[data-key="([^"]+)"\]/.exec(selector);
        return match ? (fields[match[1]] || null) : null;
      }
    };
  }
  const panel = Object.create(sandbox.FloatingPanel.prototype);
  panel.schema = sandbox.SETTINGS_SCHEMA;
  panel.settings = sandbox.ATPNormalizeSettings(storage.settings);
  panel.settings.gridCols = 6;
  storage.settings.visibleRows = 9;
  const patch = panel._cloneSettingsForSave(panel.settings, ['gridCols']);
  assert(patch.gridCols === 6, 'floating panel save patch must include the changed schema field');
  assert(!Object.prototype.hasOwnProperty.call(patch, 'visibleRows'), 'floating panel save patch must not include stale unchanged schema fields');
  assert(!Object.prototype.hasOwnProperty.call(patch, 'enabled'), 'floating panel save patch must not synthesize enabled defaults');
  assert(!Object.prototype.hasOwnProperty.call(patch, 'siteConfigs'), 'floating panel save patch must not synthesize an empty site config map');
  const storageApi = panel.defaultStorage();
  await storageApi.setSettings(patch);
  assert(storage.settings.gridCols === 6, 'floating panel partial save must persist changed schema fields');
  assert(storage.settings.visibleRows === 9, 'floating panel partial save must preserve schema fields changed by another settings context');
  assert(storage.settings.enabled === false, 'floating panel partial save must preserve the stored master disabled state');
  assert(
    storage.settings.siteConfigs &&
      storage.settings.siteConfigs['example.com'] &&
      storage.settings.siteConfigs['example.com'].disabled === true,
    'floating panel partial save must preserve site disable settings'
  );

  const fields = {
    gridCols: createField('number', 6),
    visibleRows: createField('number', 2)
  };
  const pendingPanel = Object.create(sandbox.FloatingPanel.prototype);
  pendingPanel.schema = sandbox.SETTINGS_SCHEMA;
  pendingPanel.settings = sandbox.ATPNormalizeSettings({ gridCols: 6, visibleRows: 2 });
  pendingPanel._saveSeqByKey = {};
  pendingPanel._pendingSaveByKey = {};
  pendingPanel._settingsViewEl = createSettingsView(fields);
  pendingPanel._refreshDependentFields = function() {};
  const pendingAttempt = pendingPanel._markSaveAttempt('gridCols', 6);
  pendingPanel.setSettings(Object.assign({}, pendingPanel.settings, { gridCols: 5, visibleRows: 4 }));
  assert(pendingPanel.settings.gridCols === 6, 'floating panel external refresh must not overwrite a pending field with an older value');
  assert(Number(fields.gridCols.value) === 6, 'floating panel external refresh must not redraw a pending input with an older value');
  assert(pendingPanel.settings.visibleRows === 4, 'floating panel external refresh must still update non-pending fields');
  assert(Number(fields.visibleRows.value) === 4, 'floating panel external refresh must still redraw non-pending inputs');
  assert(!fields.visibleRows.attrs['aria-invalid'], 'floating panel external refresh must clear stale numeric error state on redrawn inputs');
  assert(!fields.visibleRows.attrs['aria-describedby'], 'floating panel external refresh must detach stale numeric error descriptions on redrawn inputs');
  assert(!!pendingPanel._pendingSaveByKey.gridCols, 'floating panel must keep pending state until storage confirms the pending value');
  pendingPanel.setSettings(Object.assign({}, pendingPanel.settings, { gridCols: 6, visibleRows: 4 }));
  assert(pendingPanel._isSaveAttemptCurrent(pendingAttempt), 'floating panel matching external refresh must not clear the pending attempt by value alone');
  pendingPanel._clearPendingSaveAttempt(pendingAttempt);
  assert(!pendingPanel._pendingSaveByKey.gridCols, 'floating panel matching save completion must clear the pending save attempt by sequence');

  pendingPanel.settings.visibleRows = 4;
  const staleAttempt = pendingPanel._markSaveAttempt('visibleRows', 4);
  pendingPanel.settings.visibleRows = 5;
  const newerAttempt = pendingPanel._markSaveAttempt('visibleRows', 5);
  pendingPanel.setSettings(Object.assign({}, pendingPanel.settings, { visibleRows: 5 }));
  assert(
    pendingPanel._pendingSaveByKey.visibleRows &&
      pendingPanel._pendingSaveByKey.visibleRows.seq === newerAttempt.seq,
    'floating panel equal-valued external refresh must not clear a newer pending attempt'
  );
  pendingPanel._clearPendingSaveAttempt(staleAttempt);
  assert(
    pendingPanel._pendingSaveByKey.visibleRows &&
      pendingPanel._pendingSaveByKey.visibleRows.seq === newerAttempt.seq,
    'floating panel stale rollback must not clear a newer pending save attempt'
  );
  pendingPanel._clearPendingSaveAttempt(newerAttempt);
  assert(!pendingPanel._pendingSaveByKey.visibleRows, 'floating panel current rollback must clear its pending save attempt');

  const dirtyFields = {
    gridCols: createField('number', 6),
    visibleRows: createField('number', 2)
  };
  const dirtyPanel = Object.create(sandbox.FloatingPanel.prototype);
  dirtyPanel.schema = sandbox.SETTINGS_SCHEMA;
  dirtyPanel.settings = sandbox.ATPNormalizeSettings({ gridCols: 6, visibleRows: 2 });
  dirtyPanel._saveSeqByKey = {};
  dirtyPanel._pendingSaveByKey = {};
  dirtyPanel._dirtyInputByKey = { gridCols: true };
  dirtyPanel._settingsViewEl = createSettingsView(dirtyFields);
  dirtyPanel._refreshDependentFields = function() {};
  sandbox.document.activeElement = dirtyFields.gridCols;
  dirtyPanel.setSettings(Object.assign({}, dirtyPanel.settings, { gridCols: 5, visibleRows: 4 }));
  assert(dirtyPanel.settings.gridCols === 6, 'floating panel external refresh must not overwrite active dirty inputs before change fires');
  assert(Number(dirtyFields.gridCols.value) === 6, 'floating panel external refresh must not redraw active dirty inputs before change fires');
  assert(dirtyPanel.settings.visibleRows === 4, 'floating panel external refresh must still sync non-dirty fields while another field is active dirty');
  sandbox.document.activeElement = null;
  dirtyPanel.setSettings(Object.assign({}, dirtyPanel.settings, { gridCols: 5, visibleRows: 4 }));
  assert(dirtyPanel.settings.gridCols === 5, 'floating panel dirty input protection must release after the field is no longer active');

  const dependencyFields = {
    heavyImageOptimization: createField('checkbox', false),
    heavyImageConcurrency: createField('number', 3)
  };
  const dependencyPanel = Object.create(sandbox.FloatingPanel.prototype);
  dependencyPanel.schema = sandbox.SETTINGS_SCHEMA;
  dependencyPanel.settings = sandbox.ATPNormalizeSettings({ heavyImageOptimization: false });
  dependencyPanel._dirtyInputByKey = { heavyImageConcurrency: true };
  dependencyPanel._settingsViewEl = createSettingsView(dependencyFields);
  dependencyPanel._refreshDependentFields();
  assert(dependencyFields.heavyImageConcurrency.disabled === true, 'floating panel dependent numeric inputs must be disabled when their owner toggle is off');
  assert(!dependencyFields.heavyImageConcurrency.attrs['aria-invalid'], 'floating panel dependent disable must clear stale numeric error state');
  assert(!dependencyFields.heavyImageConcurrency.attrs['aria-describedby'], 'floating panel dependent disable must detach stale numeric error descriptions');
  assert(!dependencyPanel._dirtyInputByKey.heavyImageConcurrency, 'floating panel dependent disable must clear stale dirty input state');

  const failClosedFields = {
    gridCols: createField('number', 6),
    heavyImageOptimization: createField('checkbox', true)
  };
  const failClosedPanel = Object.create(sandbox.FloatingPanel.prototype);
  failClosedPanel.schema = sandbox.SETTINGS_SCHEMA;
  failClosedPanel.settings = sandbox.ATPNormalizeSettings({ gridCols: 6, heavyImageOptimization: true });
  failClosedPanel._settingsLoadFailed = true;
  failClosedPanel._dirtyInputByKey = { gridCols: true };
  failClosedPanel._settingsViewEl = createSettingsView(failClosedFields);
  failClosedPanel._queueSettingsSave = async function() {
    throw new Error('floating panel failed-load save guard did not run');
  };
  const failClosedMessages = [];
  failClosedPanel.showMessage = function(text) { failClosedMessages.push(text); };
  failClosedPanel._refreshDependentFields();
  assert(failClosedFields.gridCols.disabled === true, 'floating panel settings load failure must disable numeric fields');
  assert(failClosedFields.heavyImageOptimization.disabled === true, 'floating panel settings load failure must disable toggle fields');
  assert(!failClosedPanel._dirtyInputByKey.gridCols, 'floating panel settings load failure must clear dirty input state when fields are disabled');
  const failClosedSave = await failClosedPanel._saveSettings('should not save', 'gridCols', ['gridCols']);
  assert(failClosedSave === false, 'floating panel settings load failure must fail closed instead of saving defaults');
  assert(failClosedMessages.indexOf('设置读取失败，请重新打开面板后再试') !== -1, 'floating panel failed-load save guard must explain why saving is blocked');
  failClosedPanel.setSettings(sandbox.ATPNormalizeSettings({ gridCols: 4, heavyImageOptimization: true }));
  assert(failClosedPanel._settingsLoadFailed === false, 'floating panel external settings refresh must clear failed-load state');
  assert(failClosedFields.gridCols.disabled === false, 'floating panel external settings refresh must re-enable fields after a valid settings payload');

  const stalePanel = Object.create(sandbox.FloatingPanel.prototype);
  stalePanel.schema = sandbox.SETTINGS_SCHEMA;
  stalePanel.settings = { gridCols: 7 };
  stalePanel._saveStatusSeq = 0;
  stalePanel.business = {};
  stalePanel._queueSettingsSave = async function() {
    stalePanel._saveStatusSeq++;
    throw new Error('stale write failed');
  };
  const messages = [];
  stalePanel.showMessage = function(text) { messages.push(text); };
  const staleResult = await stalePanel._saveSettings('stale ok', 'gridCols');
  assert(staleResult === false, 'floating panel stale save failures must report failure so callers can keep rollback semantics correct');
  assert(messages.length === 1 && messages[0] === '保存中...', 'floating panel stale save failures must keep the current save progress message without announcing a stale error');

  const overlapPanel = Object.create(sandbox.FloatingPanel.prototype);
  overlapPanel.schema = sandbox.SETTINGS_SCHEMA;
  overlapPanel.settings = sandbox.ATPNormalizeSettings({ gridCols: 6, visibleRows: 2 });
  overlapPanel._saveStatusSeq = 0;
  overlapPanel._saveSeqByKey = {};
  overlapPanel._pendingSaveByKey = {};
  overlapPanel._settingsViewEl = createSettingsView({
    gridCols: createField('number', 6),
    visibleRows: createField('number', 4)
  });
  overlapPanel._refreshDependentFields = function() {};
  const pendingSaves = [];
  overlapPanel._queueSettingsSave = function(snapshot) {
    return new Promise(function(resolve) {
      pendingSaves.push({ snapshot: snapshot, resolve: resolve });
    });
  };
  const appliedPatches = [];
  const overlapMessages = [];
  overlapPanel.business = {
    onSettingsChange: function(patch, meta) {
      appliedPatches.push({ patch: patch, meta: meta });
    }
  };
  overlapPanel.showMessage = function(text) { overlapMessages.push(text); };

  overlapPanel.settings.gridCols = 7;
  const firstSave = overlapPanel._saveSettings('grid saved', 'gridCols', ['gridCols']);
  overlapPanel.settings.visibleRows = 4;
  const secondSave = overlapPanel._saveSettings('rows saved', 'visibleRows', ['visibleRows']);
  assert(pendingSaves.length === 2, 'floating panel overlap save test must queue two independent saves');
  pendingSaves[0].resolve(sandbox.ATPNormalizeSettings({ gridCols: 7, visibleRows: 2 }));
  await firstSave;
  pendingSaves[1].resolve(sandbox.ATPNormalizeSettings({ gridCols: 7, visibleRows: 4 }));
  await secondSave;
  assert(appliedPatches.length === 2, 'floating panel overlapping successful saves must apply every saved patch to the page');
  assert(appliedPatches[0].patch.gridCols === 7, 'floating panel stale successful save must still apply its own changed key');
  assert(appliedPatches[1].patch.visibleRows === 4, 'floating panel latest successful save must apply its own changed key');
  assert(
    overlapMessages.length === 3 &&
      overlapMessages[0] === '保存中...' &&
      overlapMessages[1] === '保存中...' &&
      overlapMessages[2] === 'rows saved，缩略图已自动重新加载',
    'floating panel overlapping saves must announce progress for each save and only the latest final success message'
  );

  const messagePanel = Object.create(sandbox.FloatingPanel.prototype);
  messagePanel.schema = sandbox.SETTINGS_SCHEMA;
  messagePanel.settings = sandbox.ATPNormalizeSettings({
    gridCols: 6,
    heavyPreviewStarvationWait: 8
  });
  messagePanel._saveStatusSeq = 0;
  messagePanel._pendingSaveByKey = {};
  messagePanel.business = {};
  messagePanel._queueSettingsSave = async function() { return null; };
  const saveMessages = [];
  messagePanel.showMessage = function(text, type) { saveMessages.push({ text: text, type: type }); };
  await messagePanel._saveSettings('reset grid', 'gridCols', ['gridCols']);
  await messagePanel._saveSettings('live reset', 'heavyPreviewStarvationWait', ['heavyPreviewStarvationWait']);
  await messagePanel._saveSettings('preset reset', 'heavyPreviewStarvationWait', ['heavyPreviewStarvationWait', 'gridCols']);
  const finalSaveMessages = saveMessages.filter(function(message) { return message.type === 'ok'; });
  assert(saveMessages.filter(function(message) { return message.text === '保存中...' && message.type === 'warn'; }).length === 3, 'floating panel saves must announce progress before queued storage writes finish');
  assert(finalSaveMessages[0].text === 'reset grid，缩略图已自动重新加载' && finalSaveMessages[0].type === 'ok', 'floating panel custom reset messages must report automatic thumbnail reloads for hot-reload settings');
  assert(finalSaveMessages[1].text === 'live reset', 'floating panel custom reset messages must not add refresh guidance for immediate settings');
  assert(finalSaveMessages[2].text === 'preset reset，缩略图已自动重新加载', 'floating panel multi-field preset messages must report the highest hot-reload apply mode');

  const ordinaryPresetPanel = Object.create(sandbox.FloatingPanel.prototype);
  ordinaryPresetPanel.schema = sandbox.SETTINGS_SCHEMA;
  ordinaryPresetPanel.settings = sandbox.ATPNormalizeSettings({
    firstScreenConcurrency: 3,
    viewportPriorityReservedSlots: 2,
    backgroundConcurrency: 1,
    ordinaryHostConcurrency: 4,
    backgroundSpeed: 'slow',
    backgroundDelayMs: 0
  });
  ordinaryPresetPanel._saveStatusSeq = 0;
  ordinaryPresetPanel._saveSeqByKey = {};
  ordinaryPresetPanel._pendingSaveByKey = {};
  ordinaryPresetPanel._dirtyInputByKey = {};
  ordinaryPresetPanel._settingsLoadFailed = false;
  ordinaryPresetPanel._settingsViewEl = createSettingsView({
    firstScreenConcurrency: createField('number', 3),
    viewportPriorityReservedSlots: createField('number', 2),
    backgroundConcurrency: createField('number', 1),
    ordinaryHostConcurrency: createField('number', 4),
    backgroundSpeed: createField('select', 'slow'),
    backgroundDelayMs: createField('number', 0)
  });
  ordinaryPresetPanel._refreshDependentFields = function() {};
  ordinaryPresetPanel._queueSettingsSave = async function() { return null; };
  ordinaryPresetPanel.business = {};
  ordinaryPresetPanel.showMessage = function() {};
  ordinaryPresetPanel.flashError = function() { throw new Error('ordinary preset unexpectedly failed'); };
  const ordinaryPresetButton = {
    dataset: { preset: 'ordinaryFast' },
    attrs: {},
    setAttribute: function(name, value) { this.attrs[name] = value; },
    removeAttribute: function(name) { delete this.attrs[name]; }
  };
  await ordinaryPresetPanel._onOrdinaryPreset(ordinaryPresetButton);
  assert(ordinaryPresetPanel.settings.firstScreenConcurrency === 12, 'floating panel fast ordinary preset must raise visible weak-image concurrency');
  assert(ordinaryPresetPanel.settings.viewportPriorityReservedSlots === 7, 'floating panel fast ordinary preset must coordinate visible reserved slots');
  assert(ordinaryPresetPanel.settings.backgroundConcurrency === 2 && ordinaryPresetPanel.settings.ordinaryHostConcurrency === 10, 'floating panel fast ordinary preset must keep offscreen and host concurrency subordinate to visible work');
  assert(ordinaryPresetPanel.settings.backgroundSpeed === 'fast' && ordinaryPresetPanel.settings.backgroundDelayMs === -1, 'floating panel fast ordinary preset must reactivate its public background speed');
  assert(ordinaryPresetPanel.settings.globalImageConcurrency === 0 && ordinaryPresetPanel.settings.viewportPendingLimit === 24, 'floating panel fast ordinary preset must reset stale global ceilings and bound pending work');
  assert(ordinaryPresetPanel.settings.imageTimeout === 8000 && ordinaryPresetPanel.settings.imageTaskDeadline === 16000, 'floating panel fast ordinary preset must bound per-attempt and whole-task waits');
  assert(ordinaryPresetButton.__bfpBusy === false && !ordinaryPresetButton.attrs['aria-disabled'], 'floating panel ordinary preset must clear focus-safe busy state after save');
}

function loadFloatingPanelClassSandbox() {
  const sandbox = {
    console: console,
    window: {
      innerWidth: 560,
      innerHeight: 630
    },
    SharedUtils: {
      isHeavyImageHost: loadSharedUtils().isHeavyImageHost,
      prepareArticleExtractionContext: loadSharedUtils().prepareArticleExtractionContext.bind(loadSharedUtils()),
      MESSAGE_TYPES: {
        SAVE_SETTINGS_PATCH: 'SAVE_SETTINGS_PATCH'
      },
      escapeHtml: function(value) {
        return String(value === null || value === undefined ? '' : value);
      }
    }
  };
  vm.createContext(sandbox);
  vm.runInContext(read('floating-panel.js') + '\nthis.FloatingPanel = FloatingPanel;', sandbox, {
    filename: 'floating-panel.js'
  });
  return sandbox;
}

function loadFloatingPanelConstructorSandbox() {
  const listeners = [];
  const timers = [];
  let storageGetCount = 0;
  let fetchCount = 0;
  const elementsById = {};

  function hasClass(el, className) {
    return String(el.className || '').split(/\s+/).indexOf(className) !== -1;
  }

  function matchesSelector(el, selector) {
    if (selector.charAt(0) === '#') return el.id === selector.substring(1);
    if (selector.charAt(0) === '.') return hasClass(el, selector.substring(1));
    return false;
  }

  function registerElement(el) {
    if (el && el.id) elementsById[el.id] = el;
  }

  function createElement(tagName) {
    const attrs = {};
    const el = {
      tagName: String(tagName || '').toUpperCase(),
      id: '',
      className: '',
      textContent: '',
      innerHTMLValue: '',
      children: [],
      parentNode: null,
      style: {},
      tabIndex: 0,
      disabled: false,
      offsetWidth: 280,
      offsetHeight: 320,
      classList: createClassList([]),
      set innerHTML(value) {
        this.innerHTMLValue = String(value || '');
        this.children = [];
        const idPattern = /<([a-z0-9-]+)([^>]*)id="([^"]+)"([^>]*)>/gi;
        let match;
        while ((match = idPattern.exec(this.innerHTMLValue))) {
          const child = createElement(match[1]);
          const attrText = (match[2] || '') + ' ' + (match[4] || '');
          child.id = match[3];
          const classMatch = /class="([^"]+)"/.exec(attrText);
          if (classMatch) {
            child.className = classMatch[1];
            child.classList = createClassList(classMatch[1].split(/\s+/).filter(Boolean));
          }
          const dataViewMatch = /data-view="([^"]+)"/.exec(attrText);
          if (dataViewMatch) child.dataset = { view: dataViewMatch[1] };
          registerElement(child);
          this.appendChild(child);
        }
      },
      get innerHTML() {
        return this.innerHTMLValue;
      },
      attachShadow: function() {
        const shadow = createElement('shadow-root');
        shadow.activeElement = null;
        shadow.appendChild = function(child) {
          child.parentNode = shadow;
          shadow.children.push(child);
          return child;
        };
        shadow.querySelector = function(selector) {
          return queryElement(shadow, selector);
        };
        return shadow;
      },
      appendChild: function(child) {
        child.parentNode = this;
        this.children.push(child);
        return child;
      },
      removeChild: function(child) {
        const idx = this.children.indexOf(child);
        if (idx !== -1) this.children.splice(idx, 1);
        child.parentNode = null;
        return child;
      },
      remove: function() {
        if (this.parentNode && this.parentNode.removeChild) this.parentNode.removeChild(this);
      },
      addEventListener: function(type, handler, options) {
        listeners.push({ target: this, type: type, handler: handler, options: options });
      },
      removeEventListener: function() {},
      setAttribute: function(name, value) {
        attrs[name] = String(value);
        if (name === 'id') {
          this.id = String(value);
          registerElement(this);
        }
        if (name === 'class') {
          this.className = String(value);
          this.classList = createClassList(this.className.split(/\s+/).filter(Boolean));
        }
      },
      getAttribute: function(name) {
        if (name === 'id') return this.id || null;
        if (name === 'class') return this.className || null;
        return Object.prototype.hasOwnProperty.call(attrs, name) ? attrs[name] : null;
      },
      removeAttribute: function(name) {
        delete attrs[name];
      },
      querySelector: function(selector) {
        return queryElement(this, selector);
      },
      querySelectorAll: function(selector) {
        const out = [];
        visitElement(this, function(node) {
          if (matchesSelector(node, selector)) out.push(node);
        });
        return out;
      },
      contains: function(target) {
        for (let node = target; node; node = node.parentNode) {
          if (node === this) return true;
        }
        return false;
      },
      closest: function(selector) {
        for (let node = this; node; node = node.parentNode) {
          if (matchesSelector(node, selector)) return node;
        }
        return null;
      },
      focus: function() {},
      blur: function() {},
      getBoundingClientRect: function() {
        return { left: 12, top: 34, right: 292, bottom: 354, width: 280, height: 320 };
      }
    };
    return el;
  }

  function visitElement(root, visitor) {
    for (let i = 0; i < root.children.length; i++) {
      const child = root.children[i];
      visitor(child);
      visitElement(child, visitor);
    }
  }

  function queryElement(root, selector) {
    if (selector.charAt(0) === '#' && elementsById[selector.substring(1)]) {
      const foundById = elementsById[selector.substring(1)];
      return root === foundById || root.contains(foundById) ? foundById : null;
    }
    let found = null;
    visitElement(root, function(node) {
      if (!found && matchesSelector(node, selector)) found = node;
    });
    return found;
  }

  const document = {
    activeElement: null,
    body: createElement('body'),
    documentElement: createElement('html'),
    createElement: createElement,
    addEventListener: function(type, handler, options) {
      listeners.push({ target: document, type: type, handler: handler, options: options });
    },
    removeEventListener: function() {},
    querySelector: function() { return null; },
    contains: function(el) {
      return !!(el && (el === this.body || this.body.contains(el)));
    }
  };
  document.documentElement.appendChild(document.body);
  document.activeElement = document.body;

  const sandbox = {
    console: console,
    document: document,
    window: {
      innerWidth: 560,
      innerHeight: 630,
      addEventListener: function(type, handler, options) {
        listeners.push({ target: sandbox.window, type: type, handler: handler, options: options });
      },
      removeEventListener: function() {}
    },
    location: { hostname: 'example.com' },
    chrome: {
      runtime: {
        getURL: function(pathName) { return pathName; },
        lastError: null,
        sendMessage: function(message, callback) { callback({ ok: true, settings: message.settingsPatch || {} }); }
      },
      storage: {
        local: {
          get: async function(key) {
            if (key === 'settings') storageGetCount++;
            return {};
          },
          set: async function() {}
        }
      }
    },
    fetch: async function() {
      fetchCount++;
      return { text: async function() { return ''; } };
    },
    setTimeout: function(callback, delay) {
      timers.push({ callback: callback, delay: delay, cleared: false });
      return timers.length;
    },
    clearTimeout: function(id) {
      if (timers[id - 1]) timers[id - 1].cleared = true;
    },
    SharedUtils: {
      isHeavyImageHost: loadSharedUtils().isHeavyImageHost,
      prepareArticleExtractionContext: loadSharedUtils().prepareArticleExtractionContext.bind(loadSharedUtils()),
      MESSAGE_TYPES: {
        SAVE_SETTINGS_PATCH: 'SAVE_SETTINGS_PATCH'
      },
      escapeHtml: function(value) {
        return String(value === null || value === undefined ? '' : value);
      }
    },
    ATPNormalizeSettings: function(raw) {
      const normalized = {};
      const input = raw || {};
      for (let i = 0; i < sandbox.SETTINGS_SCHEMA.length; i++) {
        const item = sandbox.SETTINGS_SCHEMA[i];
        normalized[item.key] = input[item.key] !== undefined ? input[item.key] : item.default;
      }
      return normalized;
    }
  };
  sandbox.window.document = document;
  sandbox.window.chrome = sandbox.chrome;
  sandbox.window.SharedUtils = sandbox.SharedUtils;
  vm.createContext(sandbox);
  vm.runInContext(read('settings-schema.js') + '\nthis.SETTINGS_SCHEMA = SETTINGS_SCHEMA;', sandbox, { filename: 'settings-schema.js' });
  vm.runInContext(read('floating-panel.js') + '\nthis.FloatingPanel = FloatingPanel;', sandbox, {
    filename: 'floating-panel.js'
  });
  sandbox.__getStorageGetCount = function() { return storageGetCount; };
  sandbox.__getFetchCount = function() { return fetchCount; };
  return sandbox;
}

function createClassList(initial) {
  const names = {};
  (initial || []).forEach(function(name) {
    names[name] = true;
  });
  return {
    contains: function(name) {
      return !!names[name];
    },
    add: function(name) {
      names[name] = true;
    },
    remove: function(name) {
      delete names[name];
    },
    toggle: function(name, force) {
      const next = force === undefined ? !names[name] : !!force;
      if (next) names[name] = true;
      else delete names[name];
      return next;
    }
  };
}

function checkFloatingPanelA11yBehavior() {
  const sandbox = loadFloatingPanelClassSandbox();
  const panel = Object.create(sandbox.FloatingPanel.prototype);

  const constructorSandbox = loadFloatingPanelConstructorSandbox();
  let ctorSettingsRenderCount = 0;
  let ctorHelpRenderCount = 0;
  const originalRenderSettings = constructorSandbox.FloatingPanel.prototype._renderSettings;
  const originalRenderHelp = constructorSandbox.FloatingPanel.prototype._renderHelp;
  constructorSandbox.FloatingPanel.prototype._renderSettings = function() {
    ctorSettingsRenderCount++;
    return originalRenderSettings.apply(this, arguments);
  };
  constructorSandbox.FloatingPanel.prototype._renderHelp = function() {
    ctorHelpRenderCount++;
    return originalRenderHelp.apply(this, arguments);
  };
  const ctorPanel = new constructorSandbox.FloatingPanel({
    title: 'verify floating panel',
    settingsSchema: constructorSandbox.SETTINGS_SCHEMA,
    initialSettings: { gridCols: 7, visibleRows: 3 }
  });
  assert(constructorSandbox.__getStorageGetCount() === 0, 'floating panel constructor must reuse initial settings instead of reading settings from storage again');
  assert(ctorSettingsRenderCount === 0, 'floating panel constructor must not render hidden settings controls during startup');
  assert(ctorHelpRenderCount === 0, 'floating panel constructor must not render hidden help content during startup');
  assert(ctorPanel.settings.gridCols === 7 && ctorPanel.settings.visibleRows === 3, 'floating panel constructor must normalize and keep provided initial settings');
  ctorPanel.open();
  assert(ctorSettingsRenderCount === 1, 'floating panel must render settings on first open');
  ctorPanel.open();
  assert(ctorSettingsRenderCount === 1, 'floating panel must not rerender settings on repeated open without settings changes');
  ctorPanel._showHelp();
  assert(ctorHelpRenderCount === 1, 'floating panel must render help only when help is first opened');
  const ctorHelpToggle = ctorPanel._panel.querySelector('#bfp-help-toggle');
  assert(ctorHelpToggle.getAttribute('aria-expanded') === 'true', 'floating panel help toggle must expose expanded state after opening help');
  assert(ctorHelpToggle.getAttribute('aria-label') === '关闭参数说明', 'floating panel help toggle label must switch to a close action after opening help');
  ctorPanel._showHelp();
  assert(ctorHelpRenderCount === 1, 'floating panel must not rerender help after it has been rendered once');
  ctorPanel._hideHelp();
  assert(ctorHelpToggle.getAttribute('aria-expanded') === 'false', 'floating panel help toggle must expose collapsed state after closing help');
  assert(ctorHelpToggle.getAttribute('aria-label') === '打开参数说明', 'floating panel help toggle label must switch back to an open action after closing help');
  ctorPanel.destroy();

  const loadingPanel = Object.create(sandbox.FloatingPanel.prototype);
  const loadingAttrs = {};
  loadingPanel._settingsViewEl = {
    innerHTML: '',
    setAttribute: function(name, value) { loadingAttrs[name] = String(value); }
  };
  loadingPanel._setSettingsLoading(true);
  assert(loadingAttrs['aria-busy'] === 'true', 'floating panel settings view must expose busy state while loading');
  assert(loadingPanel._settingsViewEl.innerHTML.indexOf('正在读取设置') !== -1, 'floating panel settings view must show a visible loading state before settings render');
  loadingPanel._setSettingsLoading(false);
  assert(loadingAttrs['aria-busy'] === 'false', 'floating panel settings view must clear busy state after loading');

  const openPanel = Object.create(sandbox.FloatingPanel.prototype);
  const openAttrs = {};
  const openClassList = createClassList(['bfp-hidden']);
  let openFocused = false;
  let openPosition = null;
  openPanel._panel = {
    offsetLeft: 12,
    offsetTop: 34,
    classList: openClassList,
    setAttribute: function(name, value) { openAttrs[name] = String(value); },
    getBoundingClientRect: function() { return { left: 12, top: 34 }; },
    querySelector: function(selector) {
      return selector === '#bfp-close' ? { focus: function() { openFocused = true; } } : null;
    }
  };
  openPanel._settingsViewEl = { classList: createClassList([]) };
  openPanel._launcher = {
    getAttribute: function() { return null; },
    setAttribute: function() {},
    removeAttribute: function() {}
  };
  openPanel._applyPosition = function(x, y) { openPosition = { x: x, y: y }; };
  openPanel.open();
  assert(openAttrs['aria-hidden'] === 'false', 'floating panel open must reveal the dialog to assistive technology');
  assert(openAttrs['aria-modal'] !== 'true', 'floating panel open must not claim modal semantics while the page remains interactive');
  assert(openPosition && openPosition.x === 12 && openPosition.y === 34, 'floating panel open test must exercise the normal open positioning path');
  assert(openFocused, 'floating panel open must still move focus into the panel');

  let hiddenPanelBlurred = false;
  let launcherFocused = false;
  const hiddenFocusedControl = {
    blur: function() { hiddenPanelBlurred = true; }
  };
  const closePanelClassList = createClassList([]);
  const closeHelpClassList = createClassList([]);
  const closePanel = Object.create(sandbox.FloatingPanel.prototype);
  closePanel._shadow = { activeElement: hiddenFocusedControl };
  closePanel._panel = {
    classList: closePanelClassList,
    contains: function(el) { return el === hiddenFocusedControl; },
    setAttribute: function(){},
    querySelector: function() { return null; }
  };
  closePanel._helpPanel = {
    classList: closeHelpClassList,
    contains: function() { return false; },
    setAttribute: function(){}
  };
  closePanel._launcher = {
    setAttribute: function(){},
    focus: function() { launcherFocused = true; }
  };
  closePanel._closeWithoutFocusRestore();
  assert(hiddenPanelBlurred, 'floating panel outside-click close must blur focus left inside the hidden panel');
  assert(!launcherFocused, 'floating panel outside-click close must not steal focus back to the launcher');

  const outsidePointerListeners = {};
  const pointerOutsidePanel = Object.create(sandbox.FloatingPanel.prototype);
  const pointerPanel = { classList: createClassList([]) };
  const pointerHelp = {};
  const pointerLauncher = {};
  const pointerRoot = {};
  let pointerClosed = 0;
  sandbox.window.PointerEvent = function() {};
  sandbox.document = {
    addEventListener: function(type, handler, options) {
      outsidePointerListeners[type] = { handler: handler, options: options };
    },
    removeEventListener: function() {}
  };
  pointerOutsidePanel._listeners = [];
  pointerOutsidePanel._panel = pointerPanel;
  pointerOutsidePanel._helpPanel = pointerHelp;
  pointerOutsidePanel._launcher = pointerLauncher;
  pointerOutsidePanel._root = pointerRoot;
  pointerOutsidePanel._closeWithoutFocusRestore = function() {
    pointerClosed++;
    pointerPanel.classList.add('bfp-hidden');
  };
  pointerOutsidePanel._bindOutsideClick();
  assert(outsidePointerListeners.pointerdown && outsidePointerListeners.pointerdown.options === true, 'floating panel outside close must bind pointerdown in the capture phase');
  assert(!outsidePointerListeners.click, 'floating panel outside close must not depend on bubbling click events');
  outsidePointerListeners.pointerdown.handler({
    composedPath: function() { return [pointerHelp, pointerPanel, pointerRoot]; }
  });
  assert(pointerClosed === 0, 'floating panel capture outside close must ignore events from the panel, help panel, launcher, or root');
  outsidePointerListeners.pointerdown.handler({
    composedPath: function() { return [{}]; }
  });
  assert(pointerClosed === 1, 'floating panel capture outside close must close when the host page would stop a later bubbling click');

  const outsideMouseListeners = {};
  const mouseOutsidePanel = Object.create(sandbox.FloatingPanel.prototype);
  delete sandbox.window.PointerEvent;
  sandbox.document = {
    addEventListener: function(type, handler, options) {
      outsideMouseListeners[type] = { handler: handler, options: options };
    },
    removeEventListener: function() {}
  };
  mouseOutsidePanel._listeners = [];
  mouseOutsidePanel._panel = { classList: createClassList(['bfp-hidden']) };
  mouseOutsidePanel._helpPanel = {};
  mouseOutsidePanel._launcher = {};
  mouseOutsidePanel._root = {};
  mouseOutsidePanel._closeWithoutFocusRestore = function() {};
  mouseOutsidePanel._bindOutsideClick();
  assert(outsideMouseListeners.mousedown && outsideMouseListeners.mousedown.options === true, 'floating panel outside close must keep a capture-phase mouse fallback without PointerEvent');

  const stacked = createClassList([]);
  const helpPanel = {
    classList: stacked,
    style: {},
    get offsetWidth() {
      return stacked.contains('bfp-help-stacked') ? 280 : 300;
    },
    get offsetHeight() {
      return stacked.contains('bfp-help-stacked') ? 320 : 480;
    }
  };
  panel._helpPanel = helpPanel;
  panel._panel = {
    getBoundingClientRect: function() {
      return { left: 20, top: 20, right: 300, bottom: 290, width: 280, height: 270 };
    }
  };
  panel._positionHelpPanel();
  assert(stacked.contains('bfp-help-stacked'), 'floating panel help must switch to stacked mode on narrow viewports');
  assert(helpPanel.style.top === '298px', 'floating panel help positioning must remeasure stacked height before choosing below-panel placement');

  const centered = createClassList([]);
  const centeredHelpPanel = {
    classList: centered,
    style: {},
    get offsetWidth() {
      return centered.contains('bfp-help-stacked') ? 280 : 300;
    },
    get offsetHeight() {
      return centered.contains('bfp-help-stacked') ? 320 : 480;
    }
  };
  panel._helpPanel = centeredHelpPanel;
  panel._panel = {
    getBoundingClientRect: function() {
      return { left: 160, top: 20, right: 440, bottom: 290, width: 280, height: 270 };
    }
  };
  sandbox.window.innerWidth = 620;
  sandbox.window.innerHeight = 630;
  panel._positionHelpPanel();
  assert(centered.contains('bfp-help-stacked'), 'floating panel help must not use beside placement when neither side can fit without overlap');
  assert(centeredHelpPanel.style.left === '160px' && centeredHelpPanel.style.top === '298px', 'floating panel centered stacked help must choose below-panel placement instead of clamped overlap');

  const docked = createClassList([]);
  const dockedPanelClasses = createClassList([]);
  const dockedHeaderAttrs = {};
  const dockedAttrs = {};
  const dockedMsgAttrs = {};
  const dockedFocusedInput = {};
  const dockedHelpBody = {};
  let dockedCloseFocused = false;
  const dockedHelpPanel = {
    classList: docked,
    style: { left: '20px', top: '20px', right: 'auto', bottom: 'auto' },
    contains: function(el) { return el === dockedHelpBody; },
    querySelector: function(selector) {
      if (selector !== '#bfp-help-close') return null;
      return { focus: function() { dockedCloseFocused = true; } };
    },
    get offsetWidth() {
      return docked.contains('bfp-help-stacked') ? 280 : 300;
    },
    get offsetHeight() {
      return docked.contains('bfp-help-stacked') ? 320 : 480;
    }
  };
  panel._helpPanel = dockedHelpPanel;
  panel._headerEl = {
    setAttribute: function(name, value) { dockedHeaderAttrs[name] = String(value); },
    removeAttribute: function(name) { delete dockedHeaderAttrs[name]; }
  };
  panel._bodyEl = {
    contains: function(el) { return el === dockedFocusedInput; },
    setAttribute: function(name, value) { dockedAttrs[name] = String(value); },
    removeAttribute: function(name) { delete dockedAttrs[name]; }
  };
  panel._msgEl = {
    setAttribute: function(name, value) { dockedMsgAttrs[name] = String(value); },
    removeAttribute: function(name) { delete dockedMsgAttrs[name]; }
  };
  panel._helpBodyEl = { focus: function() { dockedCloseFocused = true; } };
  panel._shadow = { activeElement: dockedFocusedInput };
  panel._panel = {
    classList: dockedPanelClasses,
    getBoundingClientRect: function() {
      return { left: 20, top: 20, right: 300, bottom: 290, width: 280, height: 270 };
    }
  };
  sandbox.window.innerWidth = 560;
  sandbox.window.innerHeight = 360;
  panel._positionHelpPanel();
  assert(docked.contains('bfp-help-docked'), 'floating panel help must dock inside the main panel when short viewports cannot fit it above or below');
  assert(dockedPanelClasses.contains('bfp-help-docked-open'), 'floating panel must mark the main panel while docked help is open');
  assert(dockedHelpPanel.style.left === '' && dockedHelpPanel.style.top === '', 'floating panel docked help must clear fixed viewport coordinates');
  assert(dockedHeaderAttrs['aria-hidden'] === 'true' && dockedAttrs['aria-hidden'] === 'true' && dockedMsgAttrs['aria-hidden'] === 'true', 'floating panel docked help must hide covered panel content from assistive tech');
  assert(dockedCloseFocused, 'floating panel docked help must move focus out of covered panel controls');
  dockedCloseFocused = false;
  panel._shadow.activeElement = dockedHelpBody;
  panel._positionHelpPanel();
  assert(!dockedCloseFocused, 'floating panel docked help must not steal focus when focus is already inside help');
  sandbox.window.innerHeight = 630;
  panel._positionHelpPanel();
  assert(!docked.contains('bfp-help-docked'), 'floating panel help must leave docked mode when stacked placement fits');
  assert(!dockedPanelClasses.contains('bfp-help-docked-open'), 'floating panel must clear docked-open state when normal help placement fits');
  assert(!dockedHeaderAttrs['aria-hidden'] && !dockedAttrs['aria-hidden'] && !dockedMsgAttrs['aria-hidden'], 'floating panel help must restore panel accessibility after leaving docked mode');

  const documentListeners = [];
  const shadowListeners = [];
  const arrowInput = {};
  const keyboardPanel = Object.create(sandbox.FloatingPanel.prototype);
  keyboardPanel._listeners = [];
  keyboardPanel._root = {};
  keyboardPanel._launcher = {};
  keyboardPanel._helpPanel = { classList: createClassList(['bfp-hidden']) };
  keyboardPanel._panel = {
    classList: createClassList([]),
    contains: function(el) { return el === arrowInput; }
  };
  keyboardPanel._shadow = {
    activeElement: arrowInput,
    addEventListener: function(type, handler, options) {
      shadowListeners.push({ type: type, handler: handler, options: options });
    },
    removeEventListener: function() {}
  };
  sandbox.document = {
    activeElement: arrowInput,
    querySelector: function() { return null; },
    addEventListener: function(type, handler, options) {
      documentListeners.push({ type: type, handler: handler, options: options });
    },
    removeEventListener: function() {}
  };
  keyboardPanel._bindKeyboard();
  const docKeydown = documentListeners.filter(function(item) { return item.type === 'keydown'; })[0];
  const shadowKeydown = shadowListeners.filter(function(item) { return item.type === 'keydown'; })[0];
  assert(docKeydown && docKeydown.options === true, 'floating panel document keyboard listener must keep capture handling for Escape');
  assert(shadowKeydown && shadowKeydown.options !== true, 'floating panel arrow-key isolation must run after native controls receive keydown');
  let panelTabPrevented = false;
  let panelTabStopped = false;
  let panelTabFocused = false;
  const panelTabTarget = { focus: function() { panelTabFocused = true; } };
  docKeydown.handler({
    key: 'Tab',
    composedPath: function() { return [panelTabTarget, keyboardPanel._panel, keyboardPanel._root]; },
    stopPropagation: function() { panelTabStopped = true; },
    preventDefault: function() { panelTabPrevented = true; }
  });
  assert(
    !panelTabPrevented && !panelTabStopped && !panelTabFocused,
    'floating panel non-modal dialog must leave in-panel Tab navigation to browser defaults'
  );
  let outsideTabPrevented = false;
  let outsideTabStopped = false;
  let outsideTabFocused = false;
  const outsideTabTarget = { focus: function() { outsideTabFocused = true; } };
  docKeydown.handler({
    key: 'Tab',
    composedPath: function() { return [outsideTabTarget]; },
    stopPropagation: function() { outsideTabStopped = true; },
    preventDefault: function() { outsideTabPrevented = true; }
  });
  assert(
    !outsideTabPrevented && !outsideTabStopped && !outsideTabFocused,
    'floating panel non-modal dialog must leave host-page Tab navigation to browser defaults'
  );
  let escapePrevented = false;
  let escapeStopped = false;
  let escapeClosed = false;
  keyboardPanel.close = function() { escapeClosed = true; };
  docKeydown.handler({
    key: 'Escape',
    composedPath: function() { return [outsideTabTarget]; },
    stopPropagation: function() { escapeStopped = true; },
    preventDefault: function() { escapePrevented = true; }
  });
  assert(!escapePrevented && !escapeStopped && escapeClosed, 'outside Escape must close the non-modal panel without blocking host-page handlers');
  escapeClosed = false;
  docKeydown.handler({
    key: 'Escape',
    composedPath: function() { return [arrowInput, keyboardPanel._panel, keyboardPanel._root]; },
    stopPropagation: function() { escapeStopped = true; },
    preventDefault: function() { escapePrevented = true; }
  });
  assert(escapePrevented && escapeStopped && escapeClosed, 'inside Escape must close the panel and consume the event');
  let docStoppedArrow = false;
  docKeydown.handler({
    key: 'ArrowDown',
    composedPath: function() { return [arrowInput, keyboardPanel._panel, keyboardPanel._root]; },
    stopPropagation: function() { docStoppedArrow = true; },
    preventDefault: function() {}
  });
  assert(!docStoppedArrow, 'floating panel document capture must not stop arrow keys before native controls handle them');
  let shadowStoppedArrow = false;
  shadowKeydown.handler({
    key: 'ArrowDown',
    composedPath: function() { return [arrowInput, keyboardPanel._panel, keyboardPanel._root]; },
    stopPropagation: function() { shadowStoppedArrow = true; },
    preventDefault: function() {}
  });
  assert(shadowStoppedArrow, 'floating panel shadow keyboard listener must stop handled arrow keys before they reach the host page');

  const headerListeners = {};
  const dragDocumentListeners = {};
  let capturedPointer = null;
  let releasedPointer = null;
  let dragPrevented = 0;
  let savedPosition = 0;
  let helpPositioned = 0;
  let appliedPosition = null;
  sandbox.window.PointerEvent = function() {};
  sandbox.requestAnimationFrame = function(callback) {
    callback();
    return 1;
  };
  const dragHeader = {
    addEventListener: function(type, handler) { headerListeners[type] = handler; },
    removeEventListener: function() {},
    setPointerCapture: function(pointerId) { capturedPointer = pointerId; },
    releasePointerCapture: function(pointerId) { releasedPointer = pointerId; }
  };
  const dragPanel = Object.create(sandbox.FloatingPanel.prototype);
  dragPanel._listeners = [];
  dragPanel._dragFrame = null;
  dragPanel._panel = {
    offsetLeft: 10,
    offsetTop: 20,
    offsetWidth: 280,
    offsetHeight: 320,
    style: {},
    querySelector: function(selector) { return selector === '#bfp-header' ? dragHeader : null; }
  };
  dragPanel._applyPosition = function(x, y, panelSize) {
    appliedPosition = { x: x, y: y, panelSize: panelSize };
  };
  dragPanel._savePosition = function() { savedPosition++; };
  dragPanel._positionHelpPanel = function() { helpPositioned++; };
  sandbox.document = {
    addEventListener: function(type, handler) { dragDocumentListeners[type] = handler; },
    removeEventListener: function() {}
  };
  dragPanel._bindDrag();
  assert(headerListeners.pointerdown && dragDocumentListeners.pointermove && dragDocumentListeners.pointerup && dragDocumentListeners.pointercancel, 'floating panel drag must bind touch-capable pointer events');
  assert(!headerListeners.mousedown, 'floating panel drag must avoid duplicate mouse listeners when PointerEvent is available');
  headerListeners.pointerdown({
    clientX: 30,
    clientY: 50,
    pointerId: 7,
    button: 0,
    target: { tagName: 'DIV' },
    currentTarget: dragHeader,
    preventDefault: function() { dragPrevented++; }
  });
  dragDocumentListeners.pointermove({
    clientX: 80,
    clientY: 110,
    pointerId: 7,
    preventDefault: function() { dragPrevented++; }
  });
  assert(appliedPosition && appliedPosition.x === 60 && appliedPosition.y === 80, 'floating panel pointer drag must update position from touch coordinates');
  assert(appliedPosition.panelSize.width === 280 && appliedPosition.panelSize.height === 320, 'floating panel pointer drag must reuse cached panel dimensions while moving');
  dragDocumentListeners.pointerup({ pointerId: 7 });
  assert(capturedPointer === 7 && releasedPointer === 7, 'floating panel pointer drag must capture and release the active pointer');
  assert(savedPosition === 1 && helpPositioned === 1, 'floating panel pointer drag must persist the final position and reposition help');
  assert(dragPrevented >= 2, 'floating panel pointer drag must prevent page scrolling during touch movement');
}

function checkResourcePanelFormatting() {
  const sandbox = loadResourcePanelSandbox();
  const SharedUtils = sandbox.SharedUtils;
  const panel = sandbox.window.ATPResourcePanel;
  assert(panel && typeof panel.formatAllText === 'function', 'resource panel must expose format helpers for verification');

  const passwordOnly = SharedUtils.emptyResources();
  passwordOnly.passwords = ['pass123'];
  assert(panel.formatAllText(passwordOnly) === '', 'copy-all must respect copyPasswordsWithLinks=false for password-only resources');
  assert(panel.formatPasswordsOnly(passwordOnly).indexOf('pass123') !== -1, 'explicit password copy must ignore copyPasswordsWithLinks=false');

  const linked = SharedUtils.emptyResources();
  linked.groups.baidu.push({ type: 'baidu', url: 'https://pan.baidu.com/s/1abcde', code: 'ab12', source: 'html' });
  linked.passwords = ['pass123'];
  const linkedText = panel.formatAllText(linked);
  assert(linkedText.indexOf('https://pan.baidu.com/s/1abcde') !== -1, 'copy-all must still copy links when password copying is disabled');
  assert(linkedText.indexOf('pass123') === -1, 'copy-all must omit passwords when copyPasswordsWithLinks=false');

  sandbox.window.ATPState.settings.copyPasswordsWithLinks = true;
  assert(panel.formatAllText(passwordOnly).indexOf('pass123') !== -1, 'copy-all must include password-only resources when password copying is enabled');
  assert(SharedUtils.hasResourceSource('html+txt', 'txt'), 'resource source helper must detect plus-delimited TXT sources');
  assert(!SharedUtils.hasResourceSource('html+other', 'txt'), 'resource source helper must avoid partial source matches');
  assert(SharedUtils.mergeResourceSource('html+txt', 'html') === 'html+txt', 'resource source merging must preserve ordered unique source parts');
}

function checkResourcePanelManualTextParseScheduling() {
  const sandbox = loadResourcePanelSandbox();
  const SharedUtils = sandbox.SharedUtils;
  const panel = sandbox.window.ATPResourcePanel;
  assert(panel && typeof panel._verifyRequestTextResourceManualLoad === 'function', 'resource panel must expose TXT manual scheduling helper for verification');
  assert(typeof panel._verifyShouldShowTextFallbackActions === 'function', 'resource panel must expose automatic-failure fallback visibility for verification');

  function makeThread(overrides) {
    return Object.assign({
      resources: SharedUtils.emptyResources(),
      textAttachments: [{ url: 'https://dl.ldkms.la/manual.txt', name: 'manual.txt' }],
      hasTextAttachments: true,
      textAttachmentCount: 1,
      textResourcesLoading: false,
      textResourcesDone: false,
      textResourcesRetryable: false
    }, overrides || {});
  }

  const missingRendererThread = makeThread();
  let result = panel._verifyRequestTextResourceManualLoad(missingRendererThread);
  assert(result.error === true, 'resource panel TXT manual parse must report a local error when the renderer scheduler is missing');
  assert(missingRendererThread.textResourcesLoading === false && missingRendererThread.textResourcesRetryable === true, 'resource panel TXT manual parse must keep missing-renderer failures retryable instead of stuck loading');

  let calls = 0;
  sandbox.window.ATPRenderer = {
    scheduleTextResourceLoad: function(threadState, manualRetry) {
      calls++;
      assert(manualRetry === true, 'resource panel TXT manual parse must request fail-cache bypass retries');
      assert(threadState, 'resource panel TXT manual parse must pass the active thread state');
      return false;
    }
  };
  const falseReturnThread = makeThread();
  result = panel._verifyRequestTextResourceManualLoad(falseReturnThread);
  assert(calls === 1 && result.error === true, 'resource panel TXT manual parse must treat false scheduler returns as local failures');
  assert(falseReturnThread.textResourcesLoading === false && falseReturnThread.textResourcesRetryable === true, 'resource panel TXT manual parse must keep false-return failures retryable');

  sandbox.window.ATPRenderer = {
    scheduleTextResourceLoad: function() {
      throw new Error('schedule failed');
    }
  };
  const thrownThread = makeThread();
  result = panel._verifyRequestTextResourceManualLoad(thrownThread);
  assert(result.error === true, 'resource panel TXT manual parse must catch synchronous scheduler failures');
  assert(thrownThread.textResourcesLoading === false && thrownThread.textResourcesRetryable === true, 'resource panel TXT manual parse must clear loading after synchronous scheduler failures');

  calls = 0;
  sandbox.window.ATPRenderer = {
    scheduleTextResourceLoad: function(threadState) {
      calls++;
      threadState.textResourcesLoading = true;
      threadState.textResourceMessage = 'TXT 资源解析中';
      return true;
    }
  };
  const scheduledThread = makeThread();
  result = panel._verifyRequestTextResourceManualLoad(scheduledThread);
  assert(calls === 1 && result.scheduled === true && result.error !== true, 'resource panel TXT manual parse must report successful scheduling only after the renderer accepts it');
  assert(scheduledThread.textResourcesLoading === true && scheduledThread.textResourcesRetryable === false, 'resource panel TXT manual parse must preserve renderer-owned loading state after successful scheduling');

  const importingThread = makeThread({ textResourcesImporting: true });
  result = panel._verifyRequestTextResourceManualLoad(importingThread);
  assert(result.loading === true && calls === 1, 'resource panel TXT manual parse must refuse to start while local TXT import is reading files');

  const completedThread = makeThread({ textResourcesDone: true, textResourcesRetryable: false });
  result = panel._verifyRequestTextResourceManualLoad(completedThread);
  assert(result.done === true && calls === 1, 'resource panel TXT manual parse must not reschedule completed non-retryable TXT work');

  assert(panel._verifyShouldShowTextFallbackActions(makeThread({ textResourcesAutoQueued: true })) === false, 'resource panel must hide manual TXT actions while automatic work is queued');
  assert(panel._verifyShouldShowTextFallbackActions(makeThread({ textResourcesLoading: true, textResourcesAutoActive: true })) === false, 'resource panel must hide manual TXT actions while automatic work is active');
  assert(panel._verifyShouldShowTextFallbackActions(makeThread({ textResourcesRetryable: true, textResourcesAutoAttempted: true })) === true, 'resource panel must show manual TXT actions after automatic parsing fails');
  assert(panel._verifyShouldShowTextFallbackActions(makeThread({ textResourcesDone: true, textResourcesRetryable: false, textResourcesAutoAttempted: true })) === false, 'resource panel must keep manual TXT actions hidden after automatic parsing succeeds');
}

async function checkResourcePanelClipboardSyncFailureFallback() {
  const sandbox = loadResourcePanelSandbox();
  const panel = sandbox.window.ATPResourcePanel;
  assert(panel && typeof panel._verifyCopyText === 'function', 'resource panel must expose copy helper for clipboard fallback verification');

  let clipboardCalls = 0;
  let fallbackCopies = 0;
  let selectedTextarea = false;
  const timers = [];
  const messageEl = {
    className: 'atp-resource-msg',
    textContent: '',
    setAttribute: function(name, value) { this[name] = value; }
  };
  const sourceEl = {
    querySelector: function(selector) {
      return selector === '.atp-resource-msg, .atp-resource-inline-msg' ? messageEl : null;
    }
  };
  sandbox.navigator.clipboard = {
    writeText: function() {
      clipboardCalls++;
      throw new Error('clipboard sync failure');
    }
  };
  sandbox.setTimeout = function(callback) {
    timers.push(callback);
    return timers.length;
  };
  sandbox.clearTimeout = function() {};
  sandbox.document.activeElement = { focus: function() {} };
  sandbox.document.execCommand = function(command) {
    if (command === 'copy') fallbackCopies++;
    return command === 'copy';
  };
  sandbox.document.createElement = function(tagName) {
    return {
      tagName: tagName,
      value: '',
      style: {},
      parentNode: null,
      select: function() { selectedTextarea = true; },
      remove: function() { this.parentNode = null; }
    };
  };
  sandbox.document.body = {
    appendChild: function(el) {
      el.parentNode = this;
    }
  };

  const copied = await panel._verifyCopyText('https://pan.example/item', sourceEl);
  assert(copied === true, 'resource panel clipboard sync failure must still report fallback copy success');
  assert(clipboardCalls === 1, 'resource panel clipboard sync failure test must exercise the clipboard API first');
  assert(fallbackCopies === 1 && selectedTextarea, 'resource panel clipboard sync failure must fall back to textarea copy');
  assert(timers.length === 1, 'resource panel clipboard fallback success must schedule live-region announcement');
  timers.shift()();
  assert(messageEl.textContent === '已复制', 'resource panel clipboard sync failure fallback must show success feedback');
  assert(messageEl.role === 'status' && messageEl['aria-live'] === 'polite', 'resource panel clipboard fallback success must keep polite status semantics');
}

function checkCacheNormalization() {
  const cache = loadCacheSandbox();
  const data = cache.normalizeArticleData({
    textAttachments: [
      '',
      'javascript:alert(1)',
      'https://dl.ldkms.la/file.txt?b=2&a=1#frag',
      { url: 'https://dl.ldkms.la/file.txt?a=1&b=2', name: '<b>dup</b>', source: 'legacy' },
      { url: 'https://dl.ldkms.la/second.txt', name: '<b>second.txt</b>', pageUrl: 'https://dl.ldkms.la/source.html?auth=secret#frag' },
      { url: 'http://dl.ldkms.la/insecure.txt' },
      { url: 'https://evil.example/outside.txt' },
      { url: 'https://dl.ldkms.la/third.txt', pageUrl: 'javascript:bad' },
      { url: 'https://dl.ldkms.la/fourth.txt' }
    ]
  });
  assert(data.textAttachments.length === 3, 'article cache normalization must cap TXT attachments to the shared maximum');
  assert(data.textAttachments[0].url === 'https://dl.ldkms.la/file.txt?b=2&a=1#frag', 'article cache normalization must keep the first equivalent TXT attachment');
  assert(data.textAttachments[0].source === 'txt-attachment', 'string TXT attachments must get a safe default source');
  assert(data.textAttachments[1].name === 'second.txt', 'article cache normalization must clean cached TXT attachment names');
  assert(data.textAttachments[1].pageUrl === 'https://dl.ldkms.la/source.html', 'article cache normalization must strip TXT attachment pageUrl query and hash');
  assert(!data.textAttachments[2].pageUrl, 'article cache normalization must drop invalid TXT attachment pageUrl values');
  assert(data.textAttachments.every(function(item) { return /^https:\/\//.test(item.url); }), 'article cache normalization must drop non-https TXT attachments');
  assert(data.textAttachments.every(function(item) { return item.url.indexOf('evil.example') === -1; }), 'article cache normalization must drop TXT attachments outside the fetch allowlist');
  assert(data.textAttachments.every(function(item) { return item.pageUrl !== 'javascript:bad'; }), 'article cache normalization must never persist unsafe TXT pageUrl values');
  assert(data.hasTextAttachments === true, 'article cache normalization must preserve TXT availability when clean attachments remain');
  assert(data.textAttachmentCount === data.textAttachments.length, 'article cache normalization must derive TXT counts from sanitized attachments');

  const signedMarker = cache.normalizeArticleData({
    textAttachments: [
      {
        url: 'https://xia.ewrewej.la/download?sign=secret&token=abc#frag',
        name: 'signed.txt',
        pageUrl: 'https://www.sehuatang.org/thread.html?auth=secret#post'
      },
      'https://dl.ldkms.la/private.txt?token=secret#frag'
    ],
    hasTextAttachments: false,
    textAttachmentCount: 0
  });
  assert(signedMarker.textAttachments.length === 0, 'article cache normalization must not persist signed TXT attachment URLs');
  assert(signedMarker.hasTextAttachments === true && signedMarker.textAttachmentCount === 2, 'article cache normalization must preserve markers for transient signed TXT attachments');

  const staleCount = cache.normalizeArticleData({
    textAttachments: ['https://dl.ldkms.la/one.txt'],
    hasTextAttachments: true,
    textAttachmentCount: 99
  });
  assert(staleCount.textAttachmentCount === 1, 'article cache normalization must not keep stale TXT counts when sanitized attachments remain');

  const mixedDiscuzMarker = cache.normalizeArticleData({
    textAttachments: ['https://dl.ldkms.la/external.txt'],
    hasTextAttachments: true,
    textAttachmentCount: 2
  });
  assert(mixedDiscuzMarker.textAttachments.length === 1, 'article cache normalization must keep cacheable TXT attachments in mixed marker states');
  assert(mixedDiscuzMarker.textAttachmentCount === 2, 'article cache normalization must preserve mixed Discuz TXT markers when cached attachments are only a subset');

  const dirtyOnly = cache.normalizeArticleData({
    textAttachments: ['javascript:alert(1)', ''],
    hasTextAttachments: false,
    textAttachmentCount: 9
  });
  assert(dirtyOnly.textAttachments.length === 0, 'article cache normalization must drop dirty-only TXT attachments');
  assert(dirtyOnly.hasTextAttachments === false, 'article cache normalization must clear TXT state when only dirty attachments existed');
  assert(dirtyOnly.textAttachmentCount === 0, 'article cache normalization must clear stale TXT counts when attachments are dropped');

  const discuzMarker = cache.normalizeArticleData({
    textAttachments: [],
    hasTextAttachments: true,
    textAttachmentCount: 4
  });
  assert(discuzMarker.hasTextAttachments === true && discuzMarker.textAttachmentCount === 4, 'article cache normalization must preserve Discuz re-extract markers without cached attachment URLs');

  const emptyMarker = cache.normalizeArticleData({
    textAttachments: [],
    hasTextAttachments: true,
    textAttachmentCount: 0
  });
  assert(emptyMarker.hasTextAttachments === true && emptyMarker.textAttachmentCount === 1, 'article cache normalization must preserve legacy TXT markers without cached attachment counts');
}

async function checkArticleNegativeCacheState() {
  const cache = loadCacheSandbox();
  const url = 'https://www.sehuatang.org/thread-444-1-1.html';
  const key = cache.NEGATIVE_CACHE_KEY + url;
  const negativeTtlMs = 5 * 60 * 1000;
  const ts = Date.now() - 1234;
  cache.__storage[key] = ts;

  const state = await cache.getArticleCacheState(url);
  assert(state.cached === null && state.negative === true, 'article cache state must report live negative cache hits');
  assert(state.negativeTs === ts, 'article cache state must expose the negative cache timestamp');
  assert(state.negativeExpiresAt === ts + negativeTtlMs, 'article cache state must expose the negative cache expiry time');
  assert(state.negativeRemainingMs > 0 && state.negativeRemainingMs <= negativeTtlMs, 'article cache state must expose bounded negative cache remaining time');

  cache.__storage[key] = Date.now() - negativeTtlMs - 1;
  const expiredState = await cache.getArticleCacheState(url);
  assert(expiredState.cached === null && expiredState.negative === false, 'article cache state must ignore expired negative cache entries');
  assert(!Object.prototype.hasOwnProperty.call(cache.__storage, key), 'expired negative cache entries must be removed during state reads');
}

async function checkArticleCachePartialWriteSafety() {
  const cache = loadCacheSandbox();
  const url = 'https://www.sehuatang.org/thread-888-1-1.html?extra=page%3D1#post';
  async function waitForCachedArticle(targetUrl, predicate) {
    let state = null;
    for (let i = 0; i < 12; i++) {
      await Promise.resolve();
      state = await cache.getArticleCacheState(targetUrl);
      if (state.cached && (!predicate || predicate(state.cached))) return state;
    }
    return state || cache.getArticleCacheState(targetUrl);
  }
  cache.setCachedArticleData(url, {
    images: [{ src: 'https://img.example/full-a.jpg' }],
    resources: {
      groups: {
        baidu: [{ type: 'baidu', url: 'https://pan.baidu.com/s/full', code: 'abcd', source: 'html' }]
      },
      passwords: []
    },
    loadedUrls: ['https://img.example/full-a.jpg'],
    hasTextAttachments: true,
    textAttachmentCount: 1,
    textResourcesComplete: true,
    textResourcesAttemptedCount: 1,
    textResourcesUnresolvedCount: 0,
    textResourcesRetryableCount: 0
  }, true);
  await waitForCachedArticle(url, function(data) {
    return data.images.length === 1 && data.images[0].src === 'https://img.example/full-a.jpg';
  });

  cache.setCachedArticleData(url, {
    images: [],
    resources: {
      groups: {
        magnet: [{ type: 'magnet', url: 'magnet:?xt=urn:btih:1234567890abcdef1234567890abcdef12345678', code: '', source: 'txt' }]
      },
      passwords: []
    },
    textAttachments: ['https://dl.ldkms.la/partial-resource.txt?b=2&a=1'],
    hasTextAttachments: true,
    textAttachmentCount: 2,
    loadedUrls: ['https://img.example/partial-seen.jpg'],
    partial: true
  }, false);

  const state = await waitForCachedArticle(url, function(data) {
    return data.loadedUrls.indexOf('https://img.example/partial-seen.jpg') !== -1;
  });
  assert(state.cached, 'partial article writes must not downgrade a fresh complete article cache entry');
  assert(state.cached.images.length === 1 && state.cached.images[0].src === 'https://img.example/full-a.jpg', 'partial article writes must preserve complete cached images');
  assert(state.cached.resources.groups.baidu.length === 1, 'partial article writes must preserve existing complete resources');
  assert(state.cached.resources.groups.magnet.length === 1, 'partial article writes may merge newly discovered partial resources');
  assert(state.cached.loadedUrls.indexOf('https://img.example/partial-seen.jpg') !== -1, 'partial article writes must still merge loaded URL bookkeeping');
  assert(state.cached.textAttachments.length === 1 && state.cached.textAttachments[0].url === 'https://dl.ldkms.la/partial-resource.txt?b=2&a=1', 'partial article writes must merge newly discovered TXT attachments into fresh complete caches');
  assert(state.cached.hasTextAttachments === true && state.cached.textAttachmentCount >= 2, 'partial article writes must preserve TXT availability markers after merging into complete caches');
  assert(state.cached.textResourcesComplete === false && state.cached.textResourcesUnresolvedCount >= 1, 'partial article writes that discover an additional TXT attachment must invalidate an older completed TXT cache contract');

  const markerUrl = 'https://www.sehuatang.org/thread-889-1-1.html';
  cache.setCachedArticleData(markerUrl, {
    images: [{ src: 'https://img.example/full-marker.jpg' }],
    resources: { groups: {}, passwords: [] }
  }, true);
  await waitForCachedArticle(markerUrl, function(data) {
    return data.images.length === 1 && data.images[0].src === 'https://img.example/full-marker.jpg';
  });
  cache.setCachedArticleData(markerUrl, {
    images: [],
    resources: { groups: {}, passwords: [] },
    hasTextAttachments: true,
    textAttachmentCount: 4,
    partial: true
  }, false);
  const markerState = await waitForCachedArticle(markerUrl, function(data) {
    return data.hasTextAttachments === true;
  });
  assert(markerState.cached && markerState.cached.images.length === 1, 'marker-only partial writes must not downgrade fresh complete article images');
  assert(markerState.cached.hasTextAttachments === true && markerState.cached.textAttachmentCount === 4, 'marker-only partial writes must preserve Discuz TXT attachment markers');
}

async function checkContentCacheClearGenerationBoundary() {
  const cache = loadCacheSandbox();
  const SharedUtils = cache.__SharedUtils;
  const generation = Date.now();
  cache.__storage[SharedUtils.CACHE_GENERATION_KEY] = generation;

  const staleUrl = 'https://www.sehuatang.org/thread-clear-old-1-1.html';
  const staleKey = SharedUtils.CACHE_PREFIXES.ARTICLE + SharedUtils.normalizeArticleUrl(staleUrl);
  cache.setCachedArticleData(staleUrl, {
    images: [{ src: 'https://img.example/old-cache.jpg' }],
    resources: SharedUtils.emptyResources()
  }, true, generation - 1);
  for (let i = 0; i < 12; i++) await Promise.resolve();
  assert(!Object.prototype.hasOwnProperty.call(cache.__storage, staleKey), 'content cache writes started before cache generation clears must not write article storage');
  const staleIndex = cache.__storage[SharedUtils.CACHE_INDEX_KEY];
  assert(!staleIndex || !staleIndex.entries || !staleIndex.entries[staleKey], 'content stale cache writes must not update cacheIndex');

  const freshUrl = 'https://www.sehuatang.org/thread-clear-new-1-1.html';
  cache.setCachedArticleData(freshUrl, {
    images: [{ src: 'https://img.example/new-cache.jpg' }],
    resources: SharedUtils.emptyResources()
  }, true, generation + 1);
  let freshState = null;
  for (let j = 0; j < 12; j++) {
    await Promise.resolve();
    freshState = await cache.getArticleCacheState(freshUrl);
    if (freshState.cached) break;
  }
  assert(freshState && freshState.cached && freshState.cached.images[0].src === 'https://img.example/new-cache.jpg', 'content cache writes started after cache generation clears must still be allowed');

  const raceSharedUtils = loadSharedUtils();
  const raceUrl = 'https://www.sehuatang.org/thread-clear-race-1-1.html';
  const raceKey = raceSharedUtils.CACHE_PREFIXES.ARTICLE + raceSharedUtils.normalizeArticleUrl(raceUrl);
  const raceStartedAt = Date.now();
  const newerEntry = {
    data: {
      images: [{ src: 'https://img.example/newer-cache.jpg' }],
      resources: raceSharedUtils.emptyResources(),
      textAttachments: [],
      loadedUrls: [],
      hasTextAttachments: false,
      textAttachmentCount: 0,
      retryableEmpty: false,
      emptyReason: '',
      retryAfter: 0,
      partial: false
    },
    ts: raceStartedAt + 2,
    complete: true
  };
  let contentRaceInjected = false;
  const raceCache = loadCacheSandbox({
    afterStorageSet: function(items, storage) {
      if (contentRaceInjected || !Object.prototype.hasOwnProperty.call(items, raceKey)) return;
      contentRaceInjected = true;
      storage[raceSharedUtils.CACHE_GENERATION_KEY] = raceStartedAt + 1;
      storage[raceKey] = newerEntry;
    }
  });
  raceCache.setCachedArticleData(raceUrl, {
    images: [{ src: 'https://img.example/stale-cache.jpg' }],
    resources: raceSharedUtils.emptyResources()
  }, true, raceStartedAt);
  for (let ri = 0; ri < 16; ri++) await Promise.resolve();
  assert(contentRaceInjected, 'content stale-write ownership test must inject a newer cache value after the stale set');
  assert(raceCache.__storage[raceKey] === newerEntry, 'content stale-write cleanup must not remove a newer value written to the same cache key');
}

async function checkArticleCachePositiveWriteClearsNegative() {
  const cache = loadCacheSandbox();
  const SharedUtils = loadSharedUtils();
  const url = 'https://www.sehuatang.org/thread-889-1-1.html?from=retry#post';
  const normalizedUrl = SharedUtils.normalizeArticleUrl(url);
  const negativeKey = SharedUtils.CACHE_PREFIXES.NEGATIVE + normalizedUrl;
  const indexKey = SharedUtils.CACHE_INDEX_KEY;
  cache.__storage[negativeKey] = Date.now();
  cache.__storage[indexKey] = { entries: {} };
  cache.__storage[indexKey].entries[negativeKey] = {
    t: SharedUtils.cacheIndex.TYPE.NEGATIVE,
    ts: Date.now(),
    b: 12
  };

  cache.setCachedArticleData(url, {
    images: [{ src: 'https://img.example/recovered.jpg' }],
    resources: SharedUtils.emptyResources()
  }, true);

  let state = null;
  for (let i = 0; i < 12; i++) {
    await Promise.resolve();
    state = await cache.getArticleCacheState(url);
    const index = cache.__storage[indexKey];
    if (
      state.cached &&
      !Object.prototype.hasOwnProperty.call(cache.__storage, negativeKey) &&
      index &&
      index.entries &&
      !index.entries[negativeKey]
    ) {
      break;
    }
  }
  const index = cache.__storage[indexKey];
  assert(state && state.cached && state.negative === false, 'positive article cache writes must win over stale negative cache state');
  assert(!Object.prototype.hasOwnProperty.call(cache.__storage, negativeKey), 'positive article cache writes must remove stale negative cache keys');
  assert(index && index.entries && !index.entries[negativeKey], 'positive article cache writes must remove stale negative cache index entries');
}

async function checkCacheIndexRebuildWriteFailureInvalidatesIndex() {
  const sandbox = loadSharedUtilsSandbox();
  const SharedUtils = sandbox.SharedUtils;
  const staleKey = SharedUtils.CACHE_PREFIXES.ARTICLE + 'stale';
  const liveKey = SharedUtils.CACHE_PREFIXES.ARTICLE + 'live';
  const storage = {};
  storage[liveKey] = { ts: 2, data: { images: [] }, complete: true };
  storage[SharedUtils.CACHE_INDEX_KEY] = {
    entries: {
      [staleKey]: { t: SharedUtils.cacheIndex.TYPE.ARTICLE, ts: 1, b: 10 }
    }
  };
  sandbox.console = { warn: function(){}, log: function(){}, error: function(){} };
  sandbox.chrome = {
    runtime: { lastError: null },
    storage: {
      local: {
        get: function(keys, callback) {
          if (keys === null || keys === undefined) {
            callback(Object.assign({}, storage));
            return;
          }
          const out = {};
          if (typeof keys === 'string' && Object.prototype.hasOwnProperty.call(storage, keys)) out[keys] = storage[keys];
          callback(out);
        },
        set: function(items, callback) {
          sandbox.chrome.runtime.lastError = { message: 'forced index write failure' };
          if (callback) callback();
          sandbox.chrome.runtime.lastError = null;
        },
        remove: function(keys, callback) {
          sandbox.chrome.runtime.lastError = null;
          (Array.isArray(keys) ? keys : [keys]).forEach(function(key) {
            delete storage[key];
          });
          if (callback) callback();
        }
      }
    }
  };

  const rebuilt = await new Promise(function(resolve) {
    SharedUtils.cacheIndex.rebuild(resolve);
  });
  assert(rebuilt === null, 'cacheIndex rebuild must report write failures');
  assert(!Object.prototype.hasOwnProperty.call(storage, SharedUtils.CACHE_INDEX_KEY), 'cacheIndex rebuild write failures must invalidate the stale stored index');
}

function checkCacheIndexWriteFailureSelfHealing() {
  const cache = loadCacheSandbox();
  let contentUpdateCalls = 0;
  let contentRebuildCalls = 0;
  const contentRebuildCallbacks = [];
  cache.__SharedUtils.cacheIndex.updateEntries = function(updates, callback) {
    contentUpdateCalls++;
    callback(false);
  };
  cache.__SharedUtils.cacheIndex.rebuild = function(callback) {
    contentRebuildCalls++;
    contentRebuildCallbacks.push(callback);
  };

  cache.setNegativeCache('https://www.sehuatang.org/thread-index-repair-1-1.html');
  cache.setNegativeCache('https://www.sehuatang.org/thread-index-repair-2-1.html');
  assert(contentUpdateCalls === 2, 'content cache writes must attempt each cacheIndex batch update');
  assert(contentRebuildCalls === 1, 'content cacheIndex update failures must coalesce while one repair is in flight');
  assert(
    Object.keys(cache.__storage).some(function(key) { return key.indexOf(cache.__SharedUtils.CACHE_PREFIXES.NEGATIVE) === 0; }),
    'content cacheIndex repair must not change successful cache-value write semantics'
  );
  contentRebuildCallbacks.shift()({});
  cache.setNegativeCache('https://www.sehuatang.org/thread-index-repair-3-1.html');
  assert(contentRebuildCalls === 2, 'content cacheIndex failures after a completed repair must be allowed to rebuild again');

  const background = loadBackgroundSandbox();
  let backgroundUpdateCalls = 0;
  let backgroundRebuildCalls = 0;
  const backgroundRebuildCallbacks = [];
  background.SharedUtils.cacheIndex.updateEntries = function(updates, callback) {
    backgroundUpdateCalls++;
    callback(false);
  };
  background.SharedUtils.cacheIndex.rebuild = function(callback) {
    backgroundRebuildCalls++;
    backgroundRebuildCallbacks.push(callback);
  };
  const firstBatch = {};
  firstBatch[background.SharedUtils.CACHE_PREFIXES.ARTICLE + 'repair-a'] = { ts: 1 };
  const secondBatch = {};
  secondBatch[background.SharedUtils.CACHE_PREFIXES.ARTICLE + 'repair-b'] = { ts: 2 };
  background.__updateIndexForWrite(firstBatch);
  background.__updateIndexForWrite(secondBatch);
  assert(backgroundUpdateCalls === 2, 'background cache writes must attempt each cacheIndex batch update');
  assert(backgroundRebuildCalls === 1, 'background cacheIndex update failures must coalesce while one repair is in flight');
  backgroundRebuildCallbacks.shift()({});
  background.__updateIndexForWrite(firstBatch);
  assert(backgroundRebuildCalls === 2, 'background cacheIndex failures after a completed repair must be allowed to rebuild again');
}

async function checkContentCacheIndexRemoveFailureRebuildsAfterStorageRemove() {
  const cache = loadCacheSandbox();
  const SharedUtils = cache.__SharedUtils;
  const url = 'https://www.sehuatang.org/thread-997-1-1.html?from=retry';
  const normalizedUrl = SharedUtils.normalizeArticleUrl(url);
  const negativeKey = SharedUtils.CACHE_PREFIXES.NEGATIVE + normalizedUrl;
  const indexKey = SharedUtils.CACHE_INDEX_KEY;
  cache.__storage[negativeKey] = Date.now();
  cache.__storage[indexKey] = {
    entries: {
      [negativeKey]: { t: SharedUtils.cacheIndex.TYPE.NEGATIVE, ts: 1, b: 10 }
    }
  };
  let removeCalls = 0;
  SharedUtils.cacheIndex.removeEntries = function(keys, callback) {
    removeCalls++;
    if (callback) callback(false);
  };

  cache.setCachedArticleData(url, {
    images: [{ src: 'https://img.example/recovered-index.jpg' }],
    resources: SharedUtils.emptyResources()
  }, true);

  for (let i = 0; i < 12; i++) await Promise.resolve();
  assert(removeCalls === 1, 'content cache cleanup test must force a cacheIndex removeEntries failure');
  assert(!Object.prototype.hasOwnProperty.call(cache.__storage, negativeKey), 'content cache cleanup must still remove stale negative storage keys');
  assert(
    cache.__storage[indexKey] &&
      cache.__storage[indexKey].entries &&
      !cache.__storage[indexKey].entries[negativeKey],
    'content cache cleanup must rebuild cacheIndex when removeEntries fails after storage removal'
  );
}

function checkLogSanitization() {
  const sandbox = loadLoggerSandbox();
  sandbox.Logger.init('VERIFY');
  assert(sandbox.Logger.sanitizeUrl('') === '', 'content logger must keep empty URLs empty');
  assert(sandbox.Logger.sanitizeUrl(undefined) === '', 'content logger must keep undefined URLs empty');
  assert(sandbox.Logger.sanitizeUrl(null) === '', 'content logger must keep null URLs empty');
  assert(sandbox.Logger.sanitizeUrl('img.example/path.jpg?token=abc#frag') === 'img.example/path.jpg', 'content logger must not resolve no-protocol URLs against the current page');
  assert(sandbox.Logger.sanitizeUrl('http://?token=abc#frag') === 'http://', 'content logger must sanitize malformed URLs without resolving them to the current page');
  sandbox.Logger.event('sanitize_probe', {
    url: 'https://img.example/full.jpg?token=abc#frag',
    emptyUrl: '',
    invalidUrl: 'http://?bad=1#frag',
    noProtocolUrl: 'img.example/no-protocol.jpg?token=abc#frag',
    'https://key-content.example/key.jpg?keyToken=1#key': 'keyed',
    pageUrl: 'https://www.sehuatang.org/thread-9-1-1.html?auth=secret#post',
    token: 'content-token-secret',
    access_token: 'content-access-token-secret',
    authorization: 'Bearer content-authorization-secret',
    cookie: 'content-cookie-secret',
    password: 'content-password-secret',
    nested: {
      toUrl: 'https://cdn.example/nested.png?signed=1#hash',
      signature: 'content-nested-signature-secret',
      'img-key-content.example/nested.jpg?nestedKeyToken=1#nested': 'nested-keyed'
    },
    urls: [
      'https://array.example/one.jpg?k=1#x'
    ],
    note: 'inline https://text.example/raw.jpg?private=1#inline done'
  }, 'INFO');
  sandbox.Logger.debug('plain_string', 'see https://plain.example/image.jpg?raw=1#h and //cdn-plain.example/protocol.jpg?protoToken=1#p and img.example/plain-no-protocol.jpg?bareToken=1#b and root-content.example?rootToken=1#r now');
  const circular = { url: 'https://circular.example/image.jpg?loop=1#h' };
  circular.self = circular;
  sandbox.Logger.debug('circular_probe', circular);
  let normalizeProbeReads = 0;
  const normalizeProbe = {};
  Object.defineProperty(normalizeProbe, 'url', {
    enumerable: true,
    get: function() {
      normalizeProbeReads++;
      return 'https://normalize.example/image.jpg?token=once#frag';
    }
  });
  sandbox.Logger.event('normalize_once_probe', normalizeProbe, 'INFO');
  sandbox.__storage.atp_logs_content_keys = ['atp_logs_content_keys', null, 123, 'not_a_log', 'atp_logs_content_1000_old'];
  sandbox.__storage.atp_logs_content_1000_old = [];
  sandbox.Logger.flush();

  const logKey = Object.keys(sandbox.__storage).filter(function(key) {
    return /^atp_logs_content_/.test(key) && key !== 'atp_logs_content_keys' && Array.isArray(sandbox.__storage[key]) && sandbox.__storage[key].length;
  })[0];
  assert(logKey, 'content logger sanitization test did not write a log key');
  const logs = sandbox.__storage[logKey] || [];
  const serialized = JSON.stringify(logs);
  const contentIndex = sandbox.__storage.atp_logs_content_keys || [];
  assert(contentIndex.indexOf('atp_logs_content_keys') === -1, 'content logger must not write the log index key back into the content log index');
  assert(contentIndex.indexOf(null) === -1, 'content logger must drop null entries from a dirty content log index');
  assert(contentIndex.indexOf(123) === -1, 'content logger must drop non-string entries from a dirty content log index');
  assert(contentIndex.indexOf('not_a_log') === -1, 'content logger must drop non-content-log entries from a dirty content log index');
  assert(contentIndex.indexOf(logKey) !== -1, 'content logger must keep the current content log key in the index');
  assert(serialized.indexOf('?token=') === -1, 'content logger must strip query strings from structured url fields');
  assert(serialized.indexOf('#frag') === -1, 'content logger must strip hashes from structured url fields');
  assert(serialized.indexOf('auth=secret') === -1, 'content logger must strip query strings from pageUrl fields');
  assert(serialized.indexOf('signed=1') === -1, 'content logger must strip query strings from nested url fields');
  assert(serialized.indexOf('keyToken=1') === -1, 'content logger must strip query strings from URL object keys');
  assert(serialized.indexOf('nestedKeyToken=1') === -1, 'content logger must strip query strings from nested URL object keys');
  assert(serialized.indexOf('https://www.sehuatang.org/img.example') === -1, 'content logger must not turn no-protocol URL fields into current-page URLs');
  assert(serialized.indexOf('emptyUrl":"https://') === -1, 'content logger must not turn empty URL fields into current-page URLs');
  assert(serialized.indexOf('private=1') === -1, 'content logger must strip query strings from inline text URLs');
  assert(serialized.indexOf('raw=1') === -1, 'content logger must strip query strings from plain string log data');
  assert(serialized.indexOf('protoToken=1') === -1, 'content logger must strip query strings from protocol-relative plain string URLs');
  assert(serialized.indexOf('bareToken=1') === -1, 'content logger must strip query strings from no-protocol plain string URLs');
  assert(serialized.indexOf('rootToken=1') === -1, 'content logger must strip query strings from no-protocol root plain string URLs');
  assert(serialized.indexOf('loop=1') === -1, 'content logger must sanitize circular object URL fields');
  assert(serialized.indexOf('content-token-secret') === -1, 'content logger must redact token field values');
  assert(serialized.indexOf('content-access-token-secret') === -1, 'content logger must redact access token field values');
  assert(serialized.indexOf('content-authorization-secret') === -1, 'content logger must redact authorization field values');
  assert(serialized.indexOf('content-cookie-secret') === -1, 'content logger must redact cookie field values');
  assert(serialized.indexOf('content-password-secret') === -1, 'content logger must redact password field values');
  assert(serialized.indexOf('content-nested-signature-secret') === -1, 'content logger must redact nested signature field values');
  assert(serialized.indexOf('[redacted]') !== -1, 'content logger must preserve a safe redaction marker for sensitive fields');
  assert(serialized.indexOf('[Circular]') !== -1, 'content logger must preserve a safe marker for circular fields');
  assert(serialized.indexOf('https://img.example/full.jpg') !== -1, 'content logger must keep sanitized URL origin/path context');
  assert(serialized.indexOf('https://key-content.example/key.jpg') !== -1, 'content logger must keep sanitized URL object key path context');
  assert(serialized.indexOf('img-key-content.example/nested.jpg') !== -1, 'content logger must keep sanitized nested URL object key path context');
  assert(serialized.indexOf('cdn-plain.example/protocol.jpg') !== -1, 'content logger must keep protocol-relative plain string URL path context');
  assert(serialized.indexOf('img.example/plain-no-protocol.jpg') !== -1, 'content logger must keep no-protocol plain string URL path context');
  assert(normalizeProbeReads === 1, 'content logger must normalize object log data once and reuse the sanitized fields for storage and console output');
}

function checkContentLoggerTimezoneCache() {
  let formatterCount = 0;
  const sandbox = loadLoggerSandbox({
    Intl: {
      DateTimeFormat: function() {
        formatterCount++;
        return {
          resolvedOptions: function() {
            return { timeZone: 'Etc/Verify' };
          }
        };
      }
    }
  });
  sandbox.Logger.init('VERIFY');
  sandbox.Logger.info('timezone_cache_info', { url: 'https://img.example/tz-info.jpg?token=1' });
  sandbox.Logger.event('timezone_cache_event', { url: 'https://img.example/tz-event.jpg?token=1' }, 'INFO');
  sandbox.Logger.debug('timezone_cache_debug', 'https://img.example/tz-debug.jpg?token=1');
  sandbox.Logger.flush();
  const logKey = Object.keys(sandbox.__storage).filter(function(key) {
    return /^atp_logs_content_/.test(key) && key !== 'atp_logs_content_keys' && Array.isArray(sandbox.__storage[key]) && sandbox.__storage[key].length;
  })[0];
  assert(logKey, 'content logger timezone cache test did not write a log key');
  assert(formatterCount === 1, 'content logger must cache the timezone name instead of creating an Intl formatter for every log entry');
  const logs = sandbox.__storage[logKey] || [];
  assert(logs.length >= 3, 'content logger timezone cache test must write multiple entries');
  for (let i = 0; i < logs.length; i++) {
    assert(logs[i].timezone === 'Etc/Verify', 'content logger timezone cache must preserve the resolved timezone on every entry');
  }
}

function checkContentLoggerIndexDiscovery() {
  const sandbox = loadLoggerSandbox({ enableGetKeys: true });
  sandbox.Logger.init('VERIFY');
  sandbox.__storage.atp_logs_content_keys = ['atp_logs_content_1000_indexed'];
  sandbox.__storage.atp_logs_content_1000_indexed = [{ ts: 'old-indexed' }];
  sandbox.__storage.atp_logs_content_2000_concurrent = [{ ts: 'old-concurrent' }];
  sandbox.Logger.info('index_discovery_probe', { url: 'https://img.example/index.jpg?token=secret' });
  sandbox.Logger.flush();

  const contentIndex = sandbox.__storage.atp_logs_content_keys || [];
  const currentLogKey = Object.keys(sandbox.__storage).filter(function(key) {
    return /^atp_logs_content_/.test(key) &&
      key !== 'atp_logs_content_keys' &&
      key !== 'atp_logs_content_1000_indexed' &&
      key !== 'atp_logs_content_2000_concurrent';
  })[0];
  assert(sandbox.__storageGetKeys.length > 0, 'content logger must use storage.getKeys to discover sibling content log shards before rewriting the index');
  assert(currentLogKey, 'content logger index discovery test did not write the current log shard');
  assert(contentIndex.indexOf('atp_logs_content_1000_indexed') !== -1, 'content logger index discovery must keep indexed content log shards');
  assert(contentIndex.indexOf('atp_logs_content_2000_concurrent') !== -1, 'content logger index discovery must preserve concurrent unindexed content log shards');
  assert(contentIndex.indexOf(currentLogKey) !== -1, 'content logger index discovery must keep the current content log shard');
}

function checkContentLoggerPruneRemoveFailureKeepsRetryIndex() {
  const storage = {
    atp_logs_content_keys: [],
    atp_logs_content_1000_stale: [{ ts: 'old-stale' }]
  };
  for (let i = 0; i < 20; i++) {
    const stamp = 2000 + i;
    storage['atp_logs_content_' + stamp] = [{ ts: 'new-' + i }];
    storage.atp_logs_content_keys.push('atp_logs_content_' + stamp);
  }
  storage.atp_logs_content_keys.push('atp_logs_content_1000_stale');
  const sandbox = loadLoggerSandbox({
    storage: storage,
    failStorageRemoveKeys: ['atp_logs_content_1000_stale']
  });
  sandbox.Logger.init('VERIFY');
  sandbox.Logger.info('prune_remove_failure_probe', { url: 'https://img.example/prune.jpg?secret=1' });
  sandbox.Logger.flush();

  const contentIndex = sandbox.__storage.atp_logs_content_keys || [];
  assert(sandbox.__storage.atp_logs_content_1000_stale, 'content logger prune remove failure must leave the stale shard untouched');
  assert(
    contentIndex.indexOf('atp_logs_content_1000_stale') !== -1,
    'content logger prune remove failure must keep stale shards indexed so later flushes can retry cleanup'
  );
}

