  assert(
    resources.groups.baidu.length === 1 &&
      resources.groups.baidu[0].url === 'https://pan.baidu.com/s/1contentcached',
    'content cross-origin TXT positive cache must win when TEXT_FAIL and TEXT_RESOURCE coexist'
  );
  assert(sandbox.__cacheReads.indexOf('fail:' + url) === -1, 'content cross-origin TXT positive cache hit must not read stale TEXT_FAIL entries');
  assert(sandbox.__clearedFailCache.indexOf(url) !== -1, 'content cross-origin TXT positive cache hit must clear stale TEXT_FAIL entries');
  assert(sandbox.__backgroundCalls.length === 0, 'content cross-origin TXT positive cache hit must not call the background proxy');

  const sameOriginSandbox = loadFetcherSandbox();
