  assert(threadState.resources.groups.baidu.length === 1, 'renderer TXT partial-success must merge successful resources');
  assert(threadState.textResourcesDone === false, 'renderer TXT partial-success must not mark TXT parsing complete');
  assert(threadState.textResourcesRetryable === true, 'renderer TXT partial-success must keep manual retry available');
  assert(threadState.textResourcesUnresolvedCount === 1 && threadState.textResourcesRetryableCount === 1, 'renderer TXT partial-success must store unresolved counts');
  assert(/仍有 1 个附件待重试/.test(threadState.textResourceMessage), 'renderer TXT partial-success must explain unresolved attachment retry state');
  assert(updates.some(function(update) { return update.retryable === true && update.done === false; }), 'resource panel updates must see partial-success retryable state');
  assert(cacheWrites.length === 1 && cacheWrites[0].data.textAttachmentCount === 2, 'renderer TXT partial-success cache write must keep attachment metadata for retry');

