    assert(stale.sandbox.ATPLoader.getActive() === 1, 'loader stale direct ' + label + ' must not release the fresh active slot');
    assert(thread.loaded === 0 && thread.failedCount === 0, 'loader stale direct ' + label + ' must not record success or failure for the old request');
    stale.sandbox.ATPLoader.releaseSlot(task);
